// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Para politikası ve maliye politikası (orta).
const ozEconomics9Orta = <(String, String, List<String>, String)>[
  ('Merkez bankasının günlük işlemleriyle doğrudan ve hemen etkileyebildiği, örneğin gecelik bankalararası faiz gibi değişkene ne ad verilir?', 'İşlemsel hedef', ['Nihai hedef', 'Ara hedef', 'Dışsal değişken'], 'Gecelik faiz ya da bankaların rezervleri gibi değişkenler merkez bankasının araçlarıyla kısa sürede yönlendirilebilir; bunlara işlemsel (operasyonel) hedef denir.'),
  ('Bir merkez bankası enflasyonu doğrudan kontrol edemediği için, enflasyonla güçlü ilişkisi olduğunu düşündüğü geniş para arzı büyümesini izleyip yönlendiriyor. Para arzı bu çerçevede hangi rolü üstlenir?', 'Ara hedef', ['Nihai hedef', 'Politika aracı', 'İşlemsel hedef'], 'Ara hedef, nihai hedefle istikrarlı ilişkisi olan ve işlemsel hedeften daha geniş bir değişkendir. Parasal hedeflemede para arzı bu rolü oynar.'),
  ('İyi bir ara hedef değişkeninde aranan özelliklerden biri aşağıdakilerden hangisidir?', 'Nihai hedefle istikrarlı ve öngörülebilir bir ilişkisi olması', ['Merkez bankasının hiçbir biçimde etkileyemeyeceği dışsal bir değişken olması', 'Yalnızca yıllık olarak ve uzun bir gecikmeyle ölçülebilmesi', 'Hükümet tarafından her yıl yeniden belirlenmesi'], 'Ara hedefin ölçülebilir, merkez bankasınca kontrol edilebilir ve nihai hedefle istikrarlı bir bağı olması gerekir; aksi hâlde yol gösterici olamaz.'),
  ('Kur çapası uygulayan bir ülkenin karşılaştığı en önemli bedel aşağıdakilerden hangisidir?', 'Bağımsız para politikası yürütme olanağını büyük ölçüde yitirmesi', ['Ülkenin ithalatını tamamen durdurmak ve dış ticareti yasaklamak zorunda kalması', 'Bütçe açığı veremez hâle gelmesi', 'Vergi oranlarını sabitlemek zorunda kalması'], 'Kuru sabit tutmak için faizler bağlanılan ülkenin faizlerine uyarlanmak zorundadır. Bu nedenle iç ekonomik koşullara göre faiz ayarlama esnekliği kaybolur.'),
  ('Dünyada açık enflasyon hedeflemesini ilk uygulayan merkez bankası hangi ülkeye aittir?', 'Yeni Zelanda', ['Almanya', 'Kanada', 'İsveç'], 'Yeni Zelanda Merkez Bankası 1989 tarihli yasayla fiyat istikrarına odaklandı ve 1990\'da açık enflasyon hedeflemesine geçen ilk merkez bankası oldu.'),
  ('Bir merkez bankası para politikasını hiçbir sayısal hedef açıklamadan, enflasyon, büyüme ve finansal göstergelere bakarak takdirine göre yürütüyor. Bu yaklaşım için en uygun nitelendirme hangisidir?', 'Açık bir çapası olmayan takdire dayalı politika', ['Para arzı büyümesine sayısal hedef koyan katı parasal hedefleme', 'Para kurulu düzeni', 'Açık enflasyon hedeflemesi'], 'Ne para, ne kur ne de enflasyon için açık bir sayısal hedef yoksa politika açık çapası olmayan, takdire dayalı bir yaklaşım olarak nitelenir.'),
  ('Esnek enflasyon hedeflemesinin katı enflasyon hedeflemesinden temel farkı aşağıdakilerden hangisidir?', 'Enflasyonu hedefe döndürürken üretim ve istihdamdaki dalgalanmaları da dikkate alması', ['Hiçbir sayısal enflasyon hedefi açıklamaması', 'Enflasyon hedefini her ay yeniden ve kamuoyuna duyurmadan belirlemesi', 'Döviz kurunu sabit tutmayı enflasyondan önce gelen birincil amaç sayması'], 'Esnek hedeflemede merkez bankası enflasyonu hemen değil, belli bir sürede hedefe çeker; böylece üretimdeki sert dalgalanmalardan kaçınır.'),
  ('Enflasyon hedeflemesi uygulayan bir merkez bankasının hedeften sapmalara karşı tanımladığı, örneğin hedefin iki puan altı ve üstünü kapsayan aralığa ne ad verilir?', 'Belirsizlik aralığı', ['Faiz koridoru', 'Kur bandı', 'Dalgalanma marjı'], 'Enflasyon şoklardan etkilendiği için hedefin etrafında bir belirsizlik aralığı tanımlanır; aralık dışına çıkılması özel hesap verme yükümlülüğü doğurur.'),
  ('Türkiye\'de enflasyon belirsizlik aralığının dışına çıktığında merkez bankasının hükümete gerekçeleri ve alınacak önlemleri anlatan bir yazı göndermesine ne ad verilir?', 'Açık mektup', ['Enflasyon raporu', 'Yıllık faaliyet raporu', 'Para programı'], 'Açık enflasyon hedeflemesinde TCMB, enflasyon belirsizlik aralığını aştığında hükümete ve kamuoyuna açık mektupla hesap verir.'),
  ('Enflasyon hedeflemesi uygulayan bir merkez bankasının politika faizini cari enflasyona değil, bir-iki yıl sonrası için beklenen enflasyona göre belirlemesinin nedeni hangisidir?', 'Para politikasının enflasyona etkisinin gecikmeli ortaya çıkması', ['Cari enflasyonun ölçülememesi', 'Yasaların cari enflasyona bakmayı yasaklaması', 'Beklenen enflasyonun her koşulda cari enflasyondan düşük olmasının kesin olması'], 'Faiz kararlarının fiyatlara etkisi uzun ve değişken gecikmelerle gelir. Bu yüzden enflasyon hedeflemesi ileriye dönük, tahmin temelli yürütülür.'),
  ('Bir merkez bankası enflasyon hedefini yüzde 5 olarak açıklamış, ancak gerçekleşen enflasyon üç yıl üst üste yüzde 12 civarında kalmıştır. Bu durumun en olası sonucu hangisidir?', 'Hedefin inandırıcılığı zayıflar ve beklentiler hedeften kopar', ['Beklentiler kendiliğinden yüzde 5\'e iner', 'Para politikasının gecikmeleri ortadan kalkar', 'Enflasyon hedeflemesi otomatik olarak kur çapasına dönüşür'], 'Hedefin sürekli tutturulamaması güvenilirliği aşındırır; hanehalkı ve firmalar fiyat ve ücret kararlarında hedef yerine gerçekleşmeleri esas almaya başlar.'),
  ('Türkiye\'de 2002–2005 döneminde açık enflasyon hedeflemesinden önce uygulanan, enflasyon hedefinin hükümetle belirlenip politika faizinin ana araç olarak kullanıldığı ancak tam bir hedefleme çerçevesinin henüz kurulmadığı rejime ne ad verilir?', 'Örtük enflasyon hedeflemesi', ['Para kurulu', 'Kur çapalı istikrar programı', 'Altın standardı'], 'TCMB 2002–2005 arasında örtük (üstü kapalı) enflasyon hedeflemesi uyguladı; 2006\'da açık enflasyon hedeflemesine geçildi.'),
  ('Bir merkez bankası enflasyon hedefini tek bir sayı olarak değil, yüzde 1 ile yüzde 3 arası gibi bir aralık olarak açıklıyor. Nokta hedefe göre bu tercihin bir avantajı hangisidir?', 'Kaçınılmaz şoklarda esneklik sağlayıp hedefin sık sık kaçırılmasını önlemesi', ['Enflasyonu kesinlikle ve her koşulda sıfırda tutmayı güvence altına alması', 'Beklentileri tamamen ortadan kaldırması', 'Faiz kararlarını gereksiz hâle getirmesi'], 'Aralık hedefi şoklara karşı esneklik verir; ancak beklentileri tek bir sayıya çapalamakta nokta hedef kadar net değildir.'),
  ('Enflasyon hedeflemesi uygulayan merkez bankaları neden genellikle \'beklentilerin çapalanması\'na büyük önem verir?', 'Beklentiler hedefe yakınsa şoklar fiyat ve ücretlere daha az kalıcı yansır', ['Beklentiler çapalanınca faiz kararları yasal bir zorunluluğa dönüşür', 'Çapalanan beklentiler bütçe açığını kendiliğinden ve kısa sürede kapatır', 'Beklentiler çapalanınca döviz kuru sabitlenir'], 'İnsanlar enflasyonun hedefe döneceğine inanıyorsa geçici bir fiyat şoku ücret ve fiyat ayarlamalarıyla kalıcı hâle gelmez; bu da politikanın maliyetini düşürür.'),
  ('Merkez bankası başkanının görev süresinin uzun tutulması ve süresi dolmadan kolayca görevden alınamaması bağımsızlığın hangi boyutunu güçlendirir?', 'Kurumsal (kişisel) bağımsızlığı', ['Mali bağımsızlığı', 'Kur bağımsızlığını', 'Vergi bağımsızlığını'], 'Yöneticilerin atanma ve görevden alınma güvenceleri, merkez bankası karar alıcılarının siyasi baskıdan korunmasını sağlar; bu kurumsal ya da kişisel bağımsızlıktır.'),
  ('Merkez bankasının hükümete doğrudan kredi açmasının yasayla yasaklanması bağımsızlığın hangi boyutuyla en yakından ilgilidir?', 'Mali (finansal) bağımsızlık', ['Hedef bağımsızlığı', 'Kişisel bağımsızlık', 'Siyasi temsil'], 'Hükümete kredi yasağı, kamu açıklarının para basılarak finanse edilmesini önler ve merkez bankasının bilançosunu siyasi kararlardan korur.'),
  ('İngiltere Merkez Bankası faiz belirleme konusunda araç bağımsızlığını hangi yıl kazanmıştır?', '1997', ['1946', '1979', '2008'], '1997\'de yeni hükümet faiz belirleme yetkisini İngiltere Merkez Bankası\'na devretti ve Para Politikası Kurulu oluşturuldu.'),
  ('Seçimlerden önce faizlerin indirilmesi yönünde siyasi baskıya açık bir merkez bankası için hangi sonuç beklenir?', 'Ortalama enflasyonun daha yüksek ve beklentilerin daha oynak olması', ['Enflasyonun kalıcı biçimde sıfıra inmesi ve fiyatların uzun yıllar boyunca hiç değişmemesi', 'Kamu borcunun kendiliğinden azalması', 'Döviz kurunun sabit kalması'], 'Kısa vadeli siyasi amaçlarla gevşetilen para politikası enflasyon eğilimi yaratır; piyasalar bunu bildikçe beklentiler yükselir.'),
  ('Milton Friedman\'ın para politikası için önerdiği \'k-yüzde kuralı\' neyi öngörür?', 'Para arzının her yıl sabit bir oranda artırılmasını', ['Faizin enflasyonun iki katı olarak belirlenmesini', 'Kurun her yıl yüzde k kadar düşürülmesini', 'Bütçe açığının GSYH\'nin yüzde k\'sını aşmamasını'], 'Friedman, takdire dayalı politikanın gecikmeler nedeniyle istikrarsızlaştırıcı olabileceğini düşünerek para arzının sabit bir hızla, örneğin yılda yüzde 3–5 artırılmasını önermiştir.'),
  ('Kurallara dayalı para politikasını savunanların temel gerekçelerinden biri aşağıdakilerden hangisidir?', 'Öngörülebilirlik ve güvenilirlik sağlayarak beklentileri istikrara kavuşturması', ['Beklenmedik şoklara anında ve duruma özgü esnek tepki vermeyi kolaylaştırması', 'Merkez bankasının hiçbir veri izlememesine olanak tanıması', 'Hükümetin para basmasını kolaylaştırması'], 'Kurallar merkez bankasının ne yapacağını öngörülebilir kılar ve zaman tutarsızlığı sorununu hafifletir; bedeli ise beklenmedik şoklara karşı esnekliğin azalmasıdır.'),
  ('Takdire dayalı para politikasının kurallara göre en önemli üstünlüğü hangisidir?', 'Öngörülmemiş şoklara duruma özgü tepki verebilmesi', ['Enflasyon eğilimini tamamen ortadan kaldırması', 'Beklentileri her koşulda daha iyi çapalaması', 'Merkez bankasının iletişim yapmasını gereksizleştirmesi'], 'Takdir yetkisi, kuralların öngörmediği finansal kriz gibi olağanüstü durumlarda esneklik sağlar.'),
  ('Ulysses\'in Sirenlerin şarkısına kapılmamak için kendini direğe bağlatması, para politikası literatüründe hangi fikri anlatmak için kullanılır?', 'Önceden bağlayıcı taahhütte bulunarak gelecekteki cazip sapmaları engellemek', ['Faizleri her ay değiştirerek esnek kalmak', 'Merkez bankasının kararlarını ve gerekçelerini uzun yıllar boyunca gizli tutmak', 'Para arzını tamamen piyasaya bırakmak'], 'Bu benzetme, bugünden bağlayıcı kurallar koyarak ileride kısa vadeli kazanç için hedeften sapma güdüsünün önüne geçilmesini anlatır.'),
  ('Taylor kuralı i = r* + π + 0,5(π − π*) + 0,5y biçimindedir. r* = yüzde 2, π* = yüzde 2, enflasyon π = yüzde 4 ve üretim açığı y = 0 ise önerilen politika faizi yüzde kaçtır?', '7', ['6', '8', '11'], 'i = 2 + 4 + 0,5×(4 − 2) + 0 = 7. Enflasyon hedefin 2 puan üzerinde olduğundan faiz nötr düzeyin üstüne çıkar.'),
  ('Durgunluğa giren ve enflasyonu tam hedefte olan bir ekonomide üretim açığı yüzde −4 olarak tahmin ediliyor. Nötr reel faizin ve enflasyon hedefinin yüzde 2 olduğu Taylor kuralı (i = r* + π + 0,5(π − π*) + 0,5y) hangi politika faizini önerir?', '2', ['4', '0', '−2'], 'i = 2 + 2 + 0,5×0 + 0,5×(−4) = 2. Negatif üretim açığı faizin nötr düzey olan yüzde 4\'ün altına inmesini önerir.'),
  ('Taylor kuralı i = 1 + π + 0,5(π − 2) + 0,5y biçiminde verilmiştir. Enflasyon yüzde 6, üretim açığı yüzde 2 ise politika faizi yüzde kaç olmalıdır?', '10', ['9', '11', '8'], 'i = 1 + 6 + 0,5×4 + 0,5×2 = 1 + 6 + 2 + 1 = 10.'),
  ('Taylor kuralının pratikte doğrudan uygulanmasını zorlaştıran etkenlerden biri aşağıdakilerden hangisidir?', 'Üretim açığı ve denge reel faizinin gözlenemeyip tahmin edilmesi', ['Enflasyonun hiçbir ülkede güvenilir biçimde ölçülememesi', 'Faizlerin yasayla sabitlenmiş olması', 'Kuralın yalnızca altın standardı koşullarında geçerli olması'], 'Potansiyel üretim ve nötr faiz doğrudan gözlenmez; tahminlerdeki hatalar kuralın önerdiği faizi önemli ölçüde değiştirebilir.'),
  ('Nominal politika faizi yüzde 10, beklenen enflasyon yüzde 15 olan bir ülkede para politikasının duruşu için en doğru değerlendirme hangisidir?', 'Reel faiz negatif olduğundan politika gevşektir', ['Nominal faiz pozitif olduğundan politika sıkıdır', 'Faiz enflasyondan bağımsız olduğu için duruş belirsizdir', 'Reel faiz yüzde 25 olduğundan politika çok sıkıdır'], 'Reel faiz yaklaşık 10 − 15 = −5\'tir. Negatif reel faiz borçlanmayı ve harcamayı teşvik eder; dolayısıyla duruş gevşektir.'),
  ('Nominal GSYH hedeflemesinde merkez bankası hangi büyüklüğün belirli bir hızda büyümesini hedefler?', 'Fiyat düzeyi ile reel üretimin çarpımının', ['Yalnızca enflasyondan arındırılmış reel üretimin', 'Yalnızca para tabanının', 'Yalnızca döviz rezervlerinin'], 'Nominal GSYH = fiyat düzeyi × reel GSYH. Hedef, enflasyon ve reel büyümenin toplamını kapsadığı için arz şoklarında yükü ikisi arasında paylaştırır.'),
  ('Nominal GSYH hedefi yıllık yüzde 5 olan bir ekonomide reel büyüme yüzde 1\'e düşerse hedef, kabaca hangi enflasyon oranına izin verir?', 'Yüzde 4', ['Yüzde 1', 'Yüzde 5', 'Yüzde 6'], 'Nominal büyüme ≈ enflasyon + reel büyüme olduğundan 5 − 1 = 4. Kural, büyüme yavaşlayınca daha yüksek enflasyona kendiliğinden izin verir.'),
  ('Faiz artışının firmaların net değerini ve teminat değerini düşürerek borçlanma koşullarını zorlaştırması hangi aktarım kanalına örnektir?', 'Bilanço kanalı', ['Döviz kuru kanalı', 'Senyoraj kanalı', 'Dış ticaret kanalı'], 'Bilanço kanalında faiz değişimi borçluların varlık değerini ve nakit akışını etkiler; net değeri düşen firmalar daha zor ve pahalı kredi bulur.'),
  ('Faiz indirimi hisse senedi fiyatlarını yükselterek firmaların piyasa değerinin sermaye malı maliyetinin üstüne çıkmasına ve yatırımın artmasına yol açıyor. Bu süreç hangi kuramla ilişkilidir?', 'Tobin\'in q kuramı', ['Gresham yasası', 'Ricardocu denklik', 'Wagner kanunu'], 'Tobin\'in q oranı 1\'den büyüdüğünde yeni yatırım cazip hâle gelir; para politikası hisse fiyatları üzerinden bu oranı etkiler.'),
  ('Merkez bankası sürpriz bir faiz artışı yaptığında piyasaların gelecekteki enflasyon beklentilerini aşağı çekmesiyle ücret ve fiyat artışlarının yavaşlaması hangi kanalla açıklanır?', 'Beklenti kanalı', ['Kredi tayınlaması kanalı', 'Vergi kanalı', 'Bütçe kanalı'], 'Beklenti kanalında politika kararları ve iletişim, hanehalkı ve firmaların enflasyon beklentilerini değiştirerek fiyatlama davranışlarını etkiler.'),
  ('Politika faizi artırıldığında bankaların mevduat ve kredi faizlerini ne ölçüde ve ne hızla değiştirdiğini anlatan kavram hangisidir?', 'Faiz geçişkenliği', ['Para yanılsaması', 'Kur geçişkenliği', 'Vergi yansıması'], 'Faiz geçişkenliği politika faizindeki değişikliğin piyasa faizlerine yansıma derecesidir; geçişkenlik zayıfsa para politikasının etkisi azalır.'),
  ('Konut kredilerinin çoğunluğunun değişken faizli olduğu bir ülkede politika faizinin yükseltilmesi, sabit faizli kredilerin ağır bastığı bir ülkeye göre nasıl etkiler?', 'Hanehalkının taksitleri hızla arttığı için etki daha hızlı ve güçlü olur', ['Etki tamamen ortadan kalkar', 'Taksitler düştüğü için harcamalar artar', 'Yalnızca ihracatçı firmalar etkilenir, hanehalkları faiz değişiminden etkilenmez'], 'Değişken faizli borçlarda faiz artışı mevcut borçluların ödemelerine hemen yansır; bu nedenle nakit akışı kanalı güçlü çalışır.'),
  ('Faiz artışından sonra birikimi olan emeklilerin faiz gelirinin artması, borçlu gençlerin ise kredi ödemelerinin yükselmesi para politikasının hangi etkisini gösterir?', 'Gelir ve servetin borçlular ile alacaklılar arasında yeniden dağılımı', ['Paranın uzun dönemde yansızlığı', 'Vergi yükünün tüketicilerden üreticilere yansıması', 'Likidite tuzağı'], 'Faiz değişiklikleri net borçlulardan net alacaklılara ya da tersi yönde kaynak aktarır; bu dağılım etkisi toplam harcamayı da etkileyebilir.'),
  ('Küçük ve açık bir ekonomide faiz artışı yabancı sermaye girişini çekerek ulusal parayı değerlendiriyor ve ihracatı zorlaştırıyor. Bu durumda net ihracat üzerinden işleyen kanalın toplam talebe etkisi hangi yönde olur?', 'Toplam talebi azaltır', ['Toplam talebi artırır', 'Toplam talebi etkilemez', 'Yalnızca fiyatları artırır'], 'Değerlenen para ihracatı pahalılaştırıp ithalatı ucuzlattığı için net ihracat düşer; bu da faiz artışının daraltıcı etkisini güçlendirir.'),
  ('Politika gecikmeleri sınıflandırmasında tanıma ve karar gecikmeleri birlikte hangi grubu oluşturur?', 'İç gecikme', ['Dış gecikme', 'Etki gecikmesi', 'Toplam talep gecikmesi ve uyum süresi'], 'Sorunun fark edilip politika kararının alınmasına kadar geçen süre iç gecikmedir; kararın ekonomiyi etkilemesi için geçen süre ise dış gecikmedir.'),
  ('Para politikasının iç gecikmesinin maliye politikasına göre genellikle daha kısa olmasının nedeni hangisidir?', 'Faiz kararının bir kurulca kısa sürede alınabilmesi', ['Para politikasının fiyatlara anında yansıması', 'Merkez bankasının hiç veri kullanmaması', 'Vergi kanunlarının merkez bankasınca değiştirilebilmesi ve meclise gerek olmaması'], 'Para politikası kurulu toplanıp hemen karar verebilir; vergi ve harcama değişiklikleri ise yasama sürecinden geçmek zorundadır.'),
  ('Para politikasının dış gecikmesi için en doğru ifade hangisidir?', 'Uzun ve değişkendir; etkiler bazen bir-iki yılda tamamlanır', ['Her zaman tam bir haftadır', 'Hiç yoktur; faiz kararı aynı gün enflasyonu değiştirir', 'Yalnızca maliye politikasında görülen bir olgudur, parada bulunmaz'], 'Friedman\'ın deyişiyle para politikası \'uzun ve değişken gecikmelerle\' etkiler; faiz değişikliğinin enflasyona tam etkisi çoğu zaman yıllar sürer.'),
  ('Bir merkez bankası, ekonominin durgunlukta olduğunu fark edip faizi indirmiştir; ancak etki ortaya çıktığında ekonomi zaten kendiliğinden toparlanmış ve aşırı ısınmaya başlamıştır. Bu örnek neyi gösterir?', 'Gecikmeler nedeniyle istikrar politikasının dalgalanmayı artırabileceğini', ['Para politikasının hiçbir etkisinin olmadığını', 'Maliye politikasının her zaman daha hızlı olduğunu', 'Faiz indiriminin enflasyonu kesin olarak düşürdüğünü ve fiyatları geriletebildiğini'], 'Gecikmeler yüzünden yanlış zamanda gelen uyarım, ekonomiyi dengeye çekmek yerine dalgalanmayı büyütebilir; Friedman\'ın kural önerisinin bir gerekçesi budur.'),
  ('Faiz koridorunun üst sınırı hangi merkez bankası olanağının faizine karşılık gelir?', 'Bankaların merkez bankasından gecelik borçlanma olanağı', ['Bankaların merkez bankasına gecelik borç verme olanağı', 'Hazine\'nin ihale yoluyla piyasaya sattığı uzun vadeli devlet tahvilleri', 'Zorunlu karşılıklara ödenen faiz'], 'Bankalar merkez bankasından üst sınır faiziyle her zaman borçlanabileceği için piyasada bundan yüksek faiz ödemeye razı olmaz.'),
  ('Bankacılık sisteminin merkez bankasına net olarak borçlu olduğu, yani bankaların likidite ihtiyacını merkez bankası fonlamasıyla karşıladığı durum nasıl adlandırılır?', 'Likidite açığı', ['Likidite fazlası', 'Rezerv fazlası', 'Sterilize birikim'], 'Likidite açığında bankalar ihtiyaç duydukları rezervleri merkez bankasından borçlanır; bu durumda merkez bankasının borç verme faizi piyasa faizini belirler.'),
  ('Bankacılık sisteminin likidite fazlası verdiği bir ekonomide merkez bankası faizlerin çok düşmesini önlemek için ne yapar?', 'Bankalardan borç alarak ya da ters repo yaparak fazla likiditeyi çeker', ['Bankalara ek gecelik kredi açarak sistemdeki likiditeyi daha da artırır ve faizi düşürür', 'Zorunlu karşılık oranını sıfıra indirir', 'Hazine\'ye doğrudan kredi verir'], 'Fazla likidite gecelik faizleri koridorun tabanına iter. Merkez bankası likidite çekme işlemleriyle faizi hedefe yakın tutar.'),
  ('Merkez bankasının bir menkul kıymeti piyasadan kalıcı olarak satın alıp bilançosunda tutmasına ne ad verilir?', 'Doğrudan (kesin) alım', ['Ters repo', 'Geri alım vaadiyle satış', 'Swap ve teminat işlemi'], 'Doğrudan alımda menkul kıymet geri satılmak üzere değil kalıcı olarak alınır; bu nedenle rezervleri uzun süreli artırır.'),
  ('Merkez bankasının bankalara menkul kıymet teminatı karşılığında belirli bir süre için fon verip vade sonunda fonu geri alması bankacılık sistemine ne sağlar?', 'Geçici likidite', ['Kalıcı rezerv artışı', 'Kalıcı likidite çekişi', 'Bütçe desteği ve transfer'], 'Repo işlemleri vadeli ve geri dönüşlüdür; dolayısıyla sisteme verilen likidite vade sonunda kendiliğinden geri çekilir.'),
  ('Merkez bankasının bankalara menkul kıymet satıp belirli bir süre sonra geri alma vaadinde bulunmasıyla piyasadan geçici olarak fon çekmesine ne denir?', 'Ters repo', ['Doğrudan alım', 'Parasal genişleme', 'Reeskont kredisi'], 'Merkez bankası açısından ters repoda menkul kıymet verilir, karşılığında fon alınır; böylece fazla likidite geçici olarak çekilir.'),
  ('Merkez bankası açık piyasa işlemlerinin hangi özelliği, zorunlu karşılık oranı değişikliklerine göre daha sık kullanılmasını sağlar?', 'Küçük miktarlarda ve hızla yapılıp kolayca tersine çevrilebilmesi', ['Yasa değişikliği gerektirdiği için piyasalara güçlü ve kalıcı bir siyasi sinyal vermesi', 'Bankacılık sistemini hiç etkilememesi', 'Yalnızca yılda bir kez yapılabilmesi'], 'Açık piyasa işlemleri esnek, hassas ve tersine çevrilebilirdir; bu yüzden günlük likidite yönetiminin temel aracıdır.'),
  ('Bazı merkez bankalarının zorunlu karşılık oranını günlük para politikası aracı olarak nadiren değiştirmesinin nedeni hangisidir?', 'Küçük değişikliklerin bile bankaların likiditesini sert ve kaba biçimde etkilemesi', ['Zorunlu karşılığın para arzıyla ve banka kredileriyle hiçbir ilişkisinin bulunmaması', 'Oranın yalnızca parlamento kararıyla değiştirilebilmesi', 'Bankaların zorunlu karşılık tutmasının yasak olması'], 'Oran değişikliği tüm mevduat tabanını aynı anda etkilediği için kaba bir araçtır; bu yüzden ince ayar için açık piyasa işlemleri tercih edilir.'),
  ('Bir ekonomik kriz sırasında halk bankalara güvenini yitirip mevduatını nakde çeviriyor. Nakit/mevduat oranındaki bu artış para çarpanını nasıl etkiler?', 'Azaltır', ['Artırır', 'Değiştirmez', 'Sonsuz yapar ve kontrolden çıkarır'], 'Nakit olarak tutulan para bankacılık sisteminde yeniden krediye dönüşmez; c arttıkça çarpan küçülür. Büyük Buhran\'da para arzının daralması bu yolla da gerçekleşmiştir.'),
  ('Bankalar belirsizlik nedeniyle zorunlu karşılığın üzerinde fazla rezerv tutmaya başlarsa, parasal taban değişmese bile ne olur?', 'Para çarpanı ve para arzı düşer', ['Para çarpanı yükselir ve para arzı artar', 'Yalnızca dolaşımdaki banknot artar, mevduat hiç değişmez', 'Zorunlu karşılık oranı kendiliğinden yükselir'], 'Toplam rezerv oranı r yükseldiği için çarpan küçülür; 2008 sonrasında birçok ülkede parasal taban hızla artarken geniş para aynı hızda artmamıştır.'),
  ('Basit para çarpanı yaklaşımına yöneltilen \'merkez bankası para arzını mekanik olarak belirleyemez\' eleştirisinin dayanağı hangisidir?', 'Çarpanın halkın ve bankaların davranışlarına bağlı olarak değişmesi', ['Merkez bankasının parasal tabanı hiçbir şekilde ve hiçbir araçla etkileyememesi', 'Bankaların hiç rezerv tutmaması ve çarpanın sabit kalması', 'Para arzının yalnızca Hazine tarafından belirlenmesi'], 'Nakit tercihi ve bankaların rezerv tercihi zamanla değiştiğinden çarpan istikrarsızdır; taban kontrol edilse bile para arzı tam kontrol edilemez.'),
  ('Bir hanehalkı bankasından aldığı kredinin tamamını vadesinde geri ödediğinde geniş para arzına ne olur?', 'Ödeme tutarı kadar azalır', ['Ödeme tutarı kadar artar', 'Hiç değişmez, yalnızca rezervler artar', 'İki katı kadar artar'], 'Kredi geri ödendiğinde borçlunun mevduatı silinerek bankanın alacağı kapanır; böylece kredinin yarattığı para da ortadan kalkar.'),
  ('Bir ekonomide kredi talebinin çok zayıf olduğu bir durgunlukta merkez bankası rezervleri artırsa bile geniş paranın fazla artmaması içsel para görüşüyle nasıl açıklanır?', 'Bankalar rezerv bolluğuna rağmen talep ve risk nedeniyle kredi genişletmez', ['Rezervler kanun gereği yakılıp yok edilir', 'Bankaların kredi vermesi yasaklanmıştır', 'Rezervler doğrudan hanehalkının cebine geçer ve hemen harcanarak fiyatları yükseltir'], 'Kredi yaratımı kredi talebine ve kredibilite değerlendirmesine bağlıdır; bol rezerv tek başına kredi patlaması doğurmaz.'),
  ('Merkez bankası bilançosunun yükümlülükler tarafında yer alan temel kalem hangisidir?', 'Dolaşımdaki banknotlar', ['Altın rezervleri', 'Hazine\'ye açılan krediler', 'Satın alınan devlet tahvilleri ve repo alacakları'], 'Banknotlar merkez bankasının yükümlülüğüdür; bankaların rezerv hesapları ve Hazine mevduatı da yükümlülükler arasında yer alır.'),
  ('Merkez bankası ihracatçı bankalardan 1 milyar dolar döviz satın aldığında bilançosu nasıl değişir?', 'Döviz varlıkları ve banka rezervleri aynı tutarda artar', ['Döviz varlıkları azalır, banknot yükümlülükleri ise aynı tutarda artar', 'Bilançonun yalnızca yükümlülük tarafı küçülür', 'Hiçbir kalem değişmez, işlem bilanço dışıdır'], 'Merkez bankası dövizi varlık olarak kaydeder, karşılığında bankaların lira rezervlerini artırır; bilanço iki taraflı büyür.'),
  ('Bayram öncesinde halkın bankalardan yoğun nakit çekmesi, merkez bankası müdahale etmezse bankacılık sistemindeki rezervleri nasıl etkiler?', 'Rezervleri azaltır ve likidite ihtiyacını artırır', ['Rezervleri artırır ve faizleri düşürür', 'Rezervleri değiştirmez', 'Merkez bankasının döviz rezervlerini aynı tutarda artırır'], 'Bankalar nakit ihtiyacını merkez bankasındaki hesaplarından karşılar; dolaşımdaki para artarken banka rezervleri azalır.'),
  ('2008 sonrasında ABD Merkez Bankasının bilanço büyüklüğünün birkaç katına çıkmasının temel nedeni hangisidir?', 'Büyük ölçekli varlık alım programları', ['Altın standardına geri dönülmesi', 'Federal hükümetin Fed\'e borçlarını erken ödemesi', 'Banknot basımının yasaklanması'], 'Fed, kriz sonrasında devlet tahvili ve ipoteğe dayalı menkul kıymet aldıkça bilançosu 2008 öncesindeki yaklaşık 900 milyar dolardan birkaç trilyon dolara çıktı.'),
  ('ABD Merkez Bankası Başkanı Ben Bernanke\'nin 2013\'te varlık alımlarının yavaşlatılabileceğini ima etmesinin ardından tahvil faizlerinin sert biçimde yükselmesi ve gelişmekte olan ülke paralarının değer kaybetmesi olayı hangi adla anılır?', 'Taper tantrum', ['Kara Çarşamba', 'Nixon şoku', 'Plaza Uzlaşısı'], 'Mayıs 2013\'teki açıklama piyasalarda \'tapering\' korkusuna, yani varlık alımlarının azaltılması beklentisine bağlı sert bir tepkiye yol açtı.'),
  ('Faizler sıfır alt sınırına dayandığında politika faizi daha fazla indirilemez. Bu durumda merkez bankasının harcamayı uyarmak için kullanabileceği araçlardan biri hangisidir?', 'Faizlerin uzun süre düşük tutulacağını taahhüt etmek', ['Zorunlu karşılığı yükseltmek', 'Tahvil satarak bilançoyu küçültmek', 'Politika faizini artırarak piyasalara güven vermek ve beklentileri düzeltmek'], 'Sıfır alt sınırında ileriye dönük yönlendirme beklenen kısa faiz patikasını, dolayısıyla uzun vadeli faizleri düşürerek etkili olabilir.'),
  ('Nominal faizlerin sıfırın çok altına indirilememesinin temel nedeni hangisidir?', 'İnsanların sıfır getirili nakit tutma seçeneğinin olması', ['Yasaların her koşulda faiz ödemesini zorunlu kılması', 'Bankaların zarar etmesinin teknik olarak imkânsız olması ve yasaklanması', 'Enflasyonun negatif faizle birlikte sonsuza gitmesi'], 'Faiz çok negatif olursa mevduat sahipleri parayı nakde çevirir; nakit tutmanın saklama maliyeti nedeniyle alt sınır sıfırın biraz altındadır.'),
  ('Enflasyonun negatif olduğu ve nominal faizin sıfırda takılı kaldığı bir ekonomide reel faiz için ne söylenebilir?', 'Pozitiftir ve harcamayı caydırır', ['Negatiftir ve harcamayı teşvik eder', 'Tam olarak sıfırdır ve harcamayı etkilemez', 'Merkez bankasınca anında istenen düzeye indirilebilir'], 'Reel faiz ≈ 0 − (negatif enflasyon) > 0 olur. Faiz düşürülemediği için deflasyon reel faizi istenmeyen biçimde yükseltir.'),
  ('Kamu açıklarının büyüklüğü ve finansman ihtiyacı nedeniyle merkez bankasının para politikasını enflasyon yerine hükümetin borçlanma koşullarına göre belirlemek zorunda kaldığı duruma ne ad verilir?', 'Mali baskınlık', ['Parasal baskınlık', 'Dışlama etkisi', 'Ricardocu denklik'], 'Mali baskınlıkta maliye politikası \'öne\' geçer; merkez bankası açıkları finanse etmek ya da faizi baskılamak zorunda kalır ve fiyat istikrarı ikinci plana düşer.'),
  ('Para politikasının kendi hedeflerini belirleyip maliye politikasının bütçe dengesini buna uydurmak zorunda kaldığı düzene ne ad verilir?', 'Parasal baskınlık', ['Mali baskınlık', 'Senyoraj rejimi', 'Mali yanılsama ve borç illüzyonu'], 'Parasal baskınlıkta merkez bankası açıkları finanse etmeyi reddeder; hükümet ya vergileri artırmak ya da harcamaları kısmak zorunda kalır.'),
  ('Bir ülkede para stoku 500 milyar liradır ve yıllık yüzde 20 artırılmaktadır. Basılan yeni paradan devletin elde ettiği senyoraj yaklaşık kaç milyar liradır?', '100', ['20', '520', '1.000'], 'Senyoraj ≈ para stokundaki artış = 0,20 × 500 = 100 milyar lira.'),
  ('Gelişmiş ülkelerde senyorajın kamu gelirleri içindeki payının yüksek enflasyonlu ülkelere göre çok düşük olmasının temel nedeni hangisidir?', 'Düşük enflasyon ve hükümete doğrudan merkez bankası finansmanı yasağı', ['Gelişmiş ülkelerde artık hiç banknot ve madeni para kullanılmaması', 'Merkez bankası kârlarının yasayla yok edilmesi', 'Vergi gelirlerinin sıfıra yakın olması'], 'Düşük enflasyonda para stokundaki artış küçüktür; ayrıca merkez bankası finansmanı yasakları senyorajın bütçe aracı olarak kullanılmasını sınırlar.'),
  ('Cambridge denklemi M = kPY\'de k katsayısı neyi gösterir?', 'Nominal gelirin para olarak tutulan oranını', ['Merkez bankasının belirlediği zorunlu karşılık oranının tersini', 'Reel faiz oranını', 'Fiyat düzeyindeki yıllık değişimi'], 'Cambridge yaklaşımında insanlar nominal gelirlerinin belirli bir k oranını para olarak tutmak ister; k, dolaşım hızının tersidir.'),
  ('Friedman\'ın modern miktar kuramında para talebinin temel belirleyicisi olarak öne çıkardığı değişken hangisidir?', 'Sürekli (kalıcı) gelir', ['Cari dönemin faiz oranı', 'Hükümetin bütçe dengesi', 'Altın stoku'], 'Friedman para talebini, istikrarlı bir değişken olan sürekli gelire bağlar; bu nedenle para talebinin istikrarlı olduğunu ve parasal kuralların işe yarayacağını savunur.'),
  ('Enflasyonu bir puan düşürmek için katlanılan toplam üretim kaybının (potansiyel GSYH\'nin yüzdesi olarak) ölçüsüne ne ad verilir?', 'Feda oranı', ['Okun katsayısı', 'Para çarpanı', 'Vergi kaması'], 'Feda (fedakârlık) oranı dezenflasyonun maliyetini ölçer; güvenilir politikalar bu oranı düşürebilir.'),
  ('Bir ülkede enflasyon yüzde 10\'dan yüzde 4\'e indirilirken birkaç yıl boyunca toplam olarak potansiyel GSYH\'nin yüzde 12\'si kadar üretim kaybı yaşanmıştır. Feda oranı kaçtır?', '2', ['12', '6', '0,5'], 'Feda oranı = toplam üretim kaybı / enflasyondaki düşüş = 12 / 6 = 2.'),
  ('Rasyonel beklentiler yaklaşımına göre dezenflasyonun maliyetini en çok azaltabilecek etken hangisidir?', 'Politikanın inandırıcı olması', ['Politikanın gizli tutulması', 'Kademeli ama sık sık geri adım atılması', 'Faizlerin her ay rastgele değiştirilmesi'], 'İnsanlar dezenflasyonun gerçekten uygulanacağına inanırsa beklentilerini hızla düşürür; ücret ve fiyat ayarlamaları da hızlanır, üretim kaybı azalır.'),
  ('Enflasyonun kısa sürede, sert bir parasal sıkılaştırmayla düşürülmesine dayanan yaklaşım hangi adla bilinir?', 'Soğuk duş', ['Kademecilik ve yumuşak iniş politikası', 'Fiyat düzeyi hedeflemesi', 'Gelirler politikası'], 'Soğuk duş yaklaşımı dezenflasyonu hızlı yapar; kademecilik ise yavaş ama daha az sert bir geçişi öngörür.'),
  ('Hükümetin enflasyonu düşürmek için ücret ve fiyat artışlarına doğrudan sınırlar koymasına ya da sendika ve işverenlerle uzlaşmasına dayanan politika türü hangisidir?', 'Gelirler politikası', ['Açık piyasa politikası', 'Sterilizasyon politikası', 'Kur çapası'], 'Gelirler politikası ücret-fiyat sarmalını doğrudan kırmayı amaçlar; ancak altta yatan talep baskısı sürerse etkisi geçici kalabilir.'),
  ('Merkez bankası enflasyonu düşürmeye kararlı olduğunu kanıtlamak için politika faizini piyasanın beklediğinden daha fazla artırıyor. Bu davranışın beklenen faydası hangisidir?', 'İtibar kazanarak ileride beklentileri daha düşük maliyetle yönetmek', ['Kamu borcunun faiz yükünü hemen ve kalıcı olarak azaltarak bütçe açığını tamamen kapatmak', 'Döviz kurunu sabitlemek', 'Bankaların kârlılığını artırmak'], 'Kararlılık sinyali güvenilirlik inşa eder; inandırıcı bir merkez bankasının sonraki dönemlerde beklentileri etkilemesi daha kolay ve ucuzdur.'),
  ('ABD Federal Rezerv Sistemi kaç bölgesel Federal Rezerv Bankasından oluşur?', '12', ['50', '7', '24'], '1913 Federal Rezerv Yasası ile kurulan sistemde ülke 12 bölgeye ayrılmış ve her bölgeye bir Federal Rezerv Bankası kurulmuştur.'),
  ('Avrupa Merkez Bankası\'nın para politikası kararlarını alan Yönetim Konseyi hangi üyelerden oluşur?', 'Yürütme Kurulu üyeleri ve avro bölgesi ulusal merkez bankası başkanları', ['Yalnızca avro bölgesi ülkelerinin maliye bakanları', 'Avrupa Parlamentosu\'nun her beş yılda bir kendi üyeleri arasından seçtiği milletvekilleri', 'AB\'ye üye tüm ülkelerin başbakanları'], 'Yönetim Konseyi, altı kişilik Yürütme Kurulu ile avro kullanan ülkelerin merkez bankası başkanlarından oluşur.'),
  ('İkinci Dünya Savaşı sonrası Almanya\'da 1957\'de kurulan ve yüksek bağımsızlığı ile enflasyon karşıtı tutumu sayesinde Avrupa Merkez Bankası\'na model olan merkez bankası hangisidir?', 'Deutsche Bundesbank', ['Banque de France', 'Banca d\'Italia', 'Sveriges Riksbank'], 'Bundesbank, Weimar hiperenflasyonu deneyiminin etkisiyle fiyat istikrarını öne çıkardı; AMB\'nin yapısı büyük ölçüde onun örnek alınmasıyla tasarlandı.'),
  ('Niceliksel genişleme olarak adlandırılan politikayı modern dönemde ilk uygulayan merkez bankası hangisidir?', 'Japonya Merkez Bankası', ['Avrupa Merkez Bankası', 'İngiltere Merkez Bankası', 'Kanada Merkez Bankası'], 'Japonya Merkez Bankası Mart 2001\'de işlemsel hedefini faizden banka rezervlerine çevirerek niceliksel genişlemeye başladı.'),
  ('Bundesbank 1975\'ten itibaren hangi para politikası stratejisini uygulamasıyla tanınır?', 'Parasal hedefleme', ['Kur çapası ve para kurulu', 'Getiri eğrisi kontrolü', 'Nominal GSYH hedeflemesi'], 'Bundesbank her yıl merkez bankası parası ya da geniş para için büyüme hedefleri açıkladı; bu yaklaşım Almanya\'nın düşük enflasyonuyla özdeşleşti.'),
  ('Birleşik Krallık 1992\'de enflasyon hedeflemesine hangi gelişmenin ardından geçmiştir?', 'Sterlinin Avrupa Döviz Kuru Mekanizması\'ndan çıkması', ['Avro bölgesine katılması', 'Altın standardına yeniden dönülmesi ve sterlinin altına bağlanması', 'İngiltere Merkez Bankası\'nın kamulaştırılması'], 'Eylül 1992\'deki \'Kara Çarşamba\'da sterlin ERM\'den çıktı; kur çapası kaybolunca Ekim 1992\'de enflasyon hedeflemesi benimsendi.'),
  ('1987 borsa çöküşünün ertesi günü ABD Merkez Bankasının yaptığı \'ekonomik ve finansal sisteme likidite kaynağı olarak hizmet etmeye hazırız\' açıklaması merkez bankasının hangi rolünü yansıtır?', 'Finansal istikrarın koruyucusu', ['Vergi tahsildarı', 'Dış ticaret düzenleyicisi ve kotaların belirleyicisi', 'Bütçe hazırlayıcısı'], 'Kara Pazartesi\'nin ardından Fed\'in likidite güvencesi piyasaları yatıştırdı; bu, merkez bankalarının kriz anında finansal sistemi destekleme rolüne örnektir.'),
  ('2001\'deki TCMB Kanunu değişikliğinin Hazine\'ye yönelik en önemli sonuçlarından biri hangisidir?', 'Hazine\'ye avans ve kredi verilmesinin yasaklanması', ['Hazine\'nin TCMB hisselerinin tamamına sahip olup yönetimi doğrudan ataması', 'TCMB\'nin vergi toplama yetkisi kazanması', 'Hazine\'nin faiz kararlarını onaylaması'], '4651 sayılı değişiklikle TCMB\'nin Hazine\'ye ve kamu kuruluşlarına avans vermesi ve birincil piyasadan borçlanma aracı alması yasaklandı.'),
  ('Aralık 2021\'de Türkiye\'de uygulamaya konan ve TL mevduatın getirisini döviz kurundaki artışa karşı devlet güvencesiyle telafi eden araç hangisidir?', 'Kur korumalı mevduat', ['Döviz tevdiat hesabı', 'Reeskont kredisi', 'Hazine\'nin dış piyasada Eurobond ihracı'], 'Kur korumalı mevduat, vade sonunda kur artışı faiz getirisini aşarsa aradaki farkın ödenmesini öngörüyordu; bu nedenle önemli bir mali maliyet de doğurdu.'),
  ('Türkiye\'de kronik yüksek enflasyonun yaşandığı 1990\'lar için para politikasıyla ilgili en doğru tespit hangisidir?', 'Yüksek kamu açıklarının finansman baskısı para politikasını büyük ölçüde etkisiz bıraktı', ['Merkez bankası tam bağımsızdı ve enflasyon yüzde 2\'deydi', 'Para politikası yalnızca altın stokuna göre yürütüldü', 'Kamu kesimi sürekli bütçe fazlası verdi ve borç stoku hızla azalarak sıfıra yaklaştı'], '1990\'larda kamu açıklarının büyüklüğü, merkez bankası kaynaklarının kamu finansmanına yönelmesine ve enflasyonun yüksek düzeyde kalıcılaşmasına yol açtı.'),
  ('Richard Musgrave\'in kamu maliyesinin işlevlerine ilişkin üçlü ayrımında yer alan işlevler hangileridir?', 'Tahsis, bölüşüm ve istikrar', ['Üretim, tüketim ve tasarruf', 'Planlama, örgütleme ve denetim', 'İhracat, ithalat ve rezerv biriktirme'], 'Musgrave 1959 tarihli eserinde devletin bütçe işlevlerini kaynak tahsisi, gelir bölüşümü ve ekonomik istikrar olarak üçe ayırmıştır.'),
  ('Bir ülkede devletin bütün harcama ve vergi kararlarını hem verimlilik hem hakkaniyet hem de istikrar açısından aynı anda değerlendirmesi neden zordur?', 'Bir amaca yönelik önlem diğer amaçlarla çelişebilir', ['Bu üç işlevin bütçeyle ve kamu harcamalarıyla doğrudan bir ilgisi bulunmaz', 'Vergiler yalnızca istikrar işlevine hizmet eder', 'Kamu harcamalarının gelir dağılımına etkisi yoktur'], 'Örneğin durgunlukta yapılan vergi indirimi istikrara yardım ederken gelir dağılımını bozabilir; işlevler arasında ödünleşimler vardır.'),
  ('Ekonomi tam istihdama yakınken uygulanan büyük bir genişletici maliye politikasının en olası sonucu hangisidir?', 'Üretimden çok fiyatlar artar', ['İşsizlik sıfırın altına iner', 'Fiyatlar kesin olarak düşer', 'Bütçe açığı kendiliğinden kapanır'], 'Kapasite sınırına yakın bir ekonomide ek talep büyük ölçüde fiyat artışına dönüşür; reel üretim artışı sınırlı kalır.'),
  ('Bir pandemi sırasında hükümetin işini kaybedenlere doğrudan nakit transferi yapması, kamu yatırımı yapmasına göre hangi açıdan farklıdır?', 'Mal ve hizmet alımı değil, gelir aktarımıdır', ['Toplam talebe hiçbir etkisi yoktur', 'GSYH\'nin harcama hesabında doğrudan kamu harcaması olarak sayılır', 'Yalnızca vergi gelirlerini artırır'], 'Transferler hanehalkının harcanabilir gelirini artırır ama devletin doğrudan mal-hizmet alımı (G) sayılmaz; etkileri tüketim eğilimine bağlıdır.'),
  ('Marjinal tüketim eğiliminin 0,75 olduğu kapalı ve vergileri götürü bir ekonomide vergilerin 20 milyar lira indirilmesi denge gelirini kaç milyar lira artırır?', '60', ['80', '20', '120'], 'Vergi çarpanı = −c/(1 − c) = −0,75/0,25 = −3. Vergi indirimi 20 olduğundan gelir 3 × 20 = 60 milyar lira artar.'),
  ('Basit Keynesyen modelde vergi çarpanının mutlak değerinin kamu harcaması çarpanından küçük olmasının nedeni hangisidir?', 'Vergi indiriminin bir kısmı harcanmayıp tasarruf edilir', ['Vergilerin toplam talebe hiçbir etkisi olmaz', 'Kamu harcamalarının tamamının ithal mallara yönelmesi ve yurt dışına kaçması', 'Vergi indirimleri doğrudan fiyatları düşürdüğü için'], 'Kamu harcaması ilk turda tamamen talebe eklenir; vergi indiriminde ise ilk turda yalnızca c kadarı harcanır.'),
  ('Açık ekonomilerde maliye politikası çarpanının kapalı ekonomilere göre genellikle daha küçük olmasının nedeni hangisidir?', 'Ek harcamanın bir kısmının ithalata kaçması', ['İhracatın sıfır olması', 'Vergi oranlarının açık ekonomilerde hep sıfır olması', 'Faizlerin açık ekonomilerde hiç değişmemesi'], 'Gelir arttıkça ithalat da artar; talebin bir kısmı yabancı ürünlere gittiği için yurt içi gelir artışı sınırlı kalır.'),
  ('Marjinal tüketim eğilimi 0,9 olan götürü vergili kapalı bir ekonomide devlet hanehalklarına 10 milyar liralık transfer yapıyor. Denge gelirindeki artış kaç milyar liradır?', '90', ['100', '10', '9'], 'Transfer çarpanı c/(1 − c) = 0,9/0,1 = 9; gelir artışı 9 × 10 = 90 milyar lira.'),
  ('Denge gelirinin tam istihdam gelirinin altında kaldığı durumda toplam harcamanın tam istihdamı sağlamak için ne kadar artması gerektiğini gösteren kavram hangisidir?', 'Deflasyonist (durgunluk) açık', ['Enflasyonist açık', 'Bütçe açığı', 'Cari işlemler açığı ve dış açık'], 'Deflasyonist açık, tam istihdam düzeyinde toplam harcamanın üretimin gerisinde kaldığı miktardır; kapatılması için talebin artırılması gerekir.'),
  ('Tam istihdam geliri 1.000 milyar, denge geliri 900 milyar liradır. Marjinal tüketim eğilimi 0,8 olan götürü vergili kapalı ekonomide açığı kapatmak için kamu harcaması kaç milyar lira artırılmalıdır?', '20', ['100', '25', '80'], 'Harcama çarpanı 1/(1 − 0,8) = 5\'tir. Gelirin 100 artması için kamu harcaması 100/5 = 20 milyar lira artırılmalıdır.'),
  ('Denge geliri 1.300, potansiyel gelir 1.200 milyar lira olan ve harcama çarpanı 4 olan bir ekonomide enflasyonist açığı kapatmak için kamu harcamaları ne kadar değiştirilmelidir?', '25 milyar lira azaltılmalı', ['100 milyar lira azaltılmalı', '25 milyar lira artırılmalı ve faiz düşürülmeli', '400 milyar lira azaltılmalı'], 'Gelirin 100 azalması gerekir; çarpan 4 olduğundan harcama 100/4 = 25 milyar lira kısılmalıdır.'),
  ('Likidite tuzağında, yani LM eğrisinin yatay kısmında genişletici maliye politikasının etkisi için hangisi doğrudur?', 'Faiz yükselmediği için gelir çarpan kadar artar', ['Faiz sert biçimde yükselir ve özel yatırımlar tamamen dışlanır', 'Gelir hiç değişmez', 'Gelir düşer, faiz yükselir'], 'Faiz sabit kaldığından özel yatırım dışlanmaz ve maliye politikası en güçlü hâline ulaşır. Keynesyenlerin bu durumda maliye politikasını önermesinin nedeni budur.'),
  ('IS-LM modelinde hükümet harcamaları artırırken merkez bankası faizi sabit tutmak için para arzını da artırırsa ne olur?', 'Dışlama önlenir ve gelir artışı büyür', ['Gelir artışı tamamen ortadan kalkar', 'Faiz yükselir ve yatırım azalır', 'Gelir düşer, faiz değişmez ve fiyatlar düşer'], 'Para politikasının uyumlu davranması (paranın parasallaştırılması) LM\'yi de sağa kaydırır; faiz yükselmediği için dışlama gerçekleşmez.'),
  ('Bir ekonomide gelir artırılmak isteniyor ama faizlerin değişmemesi de hedefleniyor. IS-LM modeline göre bu hedeflere hangi politika bileşimiyle ulaşılabilir?', 'Genişletici maliye ve genişletici para politikası birlikte', ['Daraltıcı maliye ve daraltıcı para politikası birlikte', 'Yalnızca daraltıcı para politikası', 'Genişletici maliye politikası ile daraltıcı para politikasının birlikte uygulanması'], 'IS ve LM\'nin birlikte sağa kayması geliri artırırken faizin aynı düzeyde kalmasını sağlayabilir.'),
  ('Jan Tinbergen\'in politika kuralına göre birbirinden bağımsız beş ekonomik hedefe aynı anda ulaşmak için en az kaç bağımsız politika aracı gerekir?', '5', ['1', '2', '10'], 'Tinbergen kuralı, hedef sayısı kadar bağımsız araç gerektiğini söyler. Araç sayısı hedeften azsa bütün hedeflere aynı anda ulaşılamaz.'),
  ('Maliye politikası çok genişletici iken para politikasının enflasyonu düşürmeye çalışması koordinasyon açısından hangi sorunu doğurur?', 'Para politikası daha sıkı olmak zorunda kalır ve faiz yükü artar', ['İki politika birbirini güçlendirir ve hiçbir ek maliyet ya da ödünleşim doğmaz', 'Enflasyon kendiliğinden sıfıra iner', 'Merkez bankası vergi oranlarını belirlemeye başlar'], 'Politikalar ters yönde çalıştığında hedefe ulaşmak için para politikası daha sert olmak zorunda kalır; yüksek faizler borç maliyetini ve dışlamayı artırır.'),
  ('Bir ekonomide hem enflasyon hem de cari açık yüksekse aynı anda ikisini de düşürmeye yönelik en tutarlı genel politika bileşimi hangisidir?', 'Talebi kısan sıkı para ve sıkı maliye politikası', ['Gevşek para ve gevşek maliye politikası', 'Vergi indirimi ve faiz indirimi birlikte', 'Yalnızca kamu harcamalarını artırmak ve ithalatı serbestleştirmek'], 'Aşırı iç talep hem fiyatları hem ithalatı artırır. Para ve maliye politikasının birlikte sıkılaştırılması talebi yavaşlatarak iki hedefe de katkı sağlar.'),
  ('Artan oranlı gelir vergisinin otomatik istikrarlandırıcı etkisi en doğru biçimde nasıl açıklanır?', 'Gelir düşünce vergiler daha hızlı düşer, harcanabilir gelir daha az azalır', ['Gelir düştüğünde vergi oranları her seferinde meclis kararıyla ve yeni bir yasa çıkarılarak yükseltilir', 'Vergi gelirleri ekonomik dalgalanmadan hiç etkilenmez', 'Gelir arttığında vergiler azalarak harcamayı hızlandırır'], 'Dilimli vergide gelir düşünce kişi daha düşük dilime iner; vergi gelirle orantıdan fazla azalır ve tüketim düşüşü yumuşar.'),
  ('Otomatik istikrarlandırıcıların güçlü olduğu bir ülkede, bir resesyon sırasında hükümet hiçbir yeni karar almasa bile bütçe dengesinde ne gözlenir?', 'Bütçe açığı büyür', ['Bütçe fazlası büyür', 'Bütçe dengesi değişmez', 'Kamu borcu kendiliğinden ve hızla sıfıra iner'], 'Resesyonda vergi gelirleri azalır, sosyal harcamalar artar; bütçe açığı kendiliğinden genişler. Bu açığın bir kısmı döngüseldir.'),
  ('Otomatik istikrarlandırıcıların tek başına bir resesyonu önlemeye neden yetmediği söylenir?', 'Dalgalanmanın yalnızca bir kısmını telafi ederler', ['Resesyonu her zaman derinleştirirler', 'Yalnızca enflasyon döneminde çalışırlar', 'Yasa gereği yalnızca beş yılda bir devreye girerler'], 'İstikrarlandırıcılar gelirdeki düşüşün belirli bir oranını dengeler; büyük şoklarda takdire bağlı ek önlemler gerekebilir.'),
  ('Maliye politikasında yasama gecikmesinin, para politikasına göre daha belirgin olmasının nedeni hangisidir?', 'Vergi ve harcama değişikliklerinin meclis sürecinden geçmesi gerekmesi', ['Maliye politikasının hiçbir zaman veri kullanmaması', 'Kamu harcamalarının merkez bankasınca belirlenmesi', 'Vergi değişikliklerinin her durumda geriye dönük olarak uygulanmak zorunda olması ve bu yüzden ertelenmesi'], 'Bütçe ve vergi kanunları tartışma, komisyon ve oylama süreçlerinden geçer; bu nedenle karar gecikmesi uzayabilir.'),
  ('Durgunlukla mücadele için başlatılan büyük bir köprü projesinin planlama ve ihale süreçleri nedeniyle harcamaların ancak üç yıl sonra yapılabilmesi hangi soruna örnektir?', 'Uygulama gecikmesi', ['Tanıma gecikmesi', 'Ricardocu denklik', 'Para yanılsaması ve beklenti hatası'], 'Karar alınsa bile kamu yatırımlarının hayata geçmesi zaman alır; harcama gerçekleştiğinde ekonomi çoktan toparlanmış olabilir.'),
  ('Durgunlukla mücadelede takdire bağlı maliye önlemlerinin \'zamanında, hedefli ve geçici\' olması önerisinin amacı hangisidir?', 'Talebi gerektiği anda desteklerken kalıcı açık yaratmamak', ['Önlemlerin hiçbir zaman uygulanmamasını sağlamak', 'Vergi sistemini kalıcı olarak değiştirmek', 'Kamu borcunu sürekli artırarak faiz dışı açığı kalıcı biçimde yüksek bir düzeyde tutmak'], 'Önlemler gecikmeden etki etmeli, en çok harcayacak kesimlere yönelmeli ve ekonomi toparlanınca sona ererek uzun vadeli mali dengeyi bozmamalıdır.'),
  ('Kamu kesimi borçlanma gereği (KKBG) neyi ölçer?', 'Kamu kesiminin finansman açığını, yani borçlanma ihtiyacını', ['Merkez bankasının döviz rezervlerini', 'Özel sektörün yurt dışı borçlarını', 'Bankaların merkez bankasında tuttuğu zorunlu karşılık tutarlarını ve serbest mevduatlarını'], 'KKBG, genişletilmiş kamu kesiminin gelirleri ile giderleri arasındaki farkı, yani borçlanmayla kapatılması gereken açığı gösterir.'),
  ('Bir ülkede toplam bütçe açığı GSYH\'nin yüzde 4\'ü, döngüsel bileşen ise yüzde 3\'üdür. Yapısal bütçe açığı GSYH\'nin yüzde kaçıdır?', '1', ['7', '3', '4,5'], 'Yapısal açık = toplam açık − döngüsel açık = 4 − 3 = 1. Açığın büyük kısmı durgunluktan kaynaklanmaktadır.'),
  ('Faiz dışı fazla verdiği hâlde toplam bütçe açığı veren bir ülke için hangisi kesin olarak söylenebilir?', 'Faiz giderleri faiz dışı fazladan büyüktür', ['Vergi gelirleri sıfırdır', 'Kamu borcu hiç yoktur', 'Faiz ödemeleri faiz dışı fazladan küçüktür ve borç azalıyordur'], 'Toplam denge = faiz dışı denge − faiz giderleri. Faiz dışı denge pozitifken toplam denge negatifse faiz giderleri fazladan büyüktür.'),
  ('Devletin bütün gelir ve giderlerinin tek bir belgede toplanmasını öngören bütçe ilkesi hangisidir?', 'Birlik ilkesi', ['Yıllık olma ilkesi ve dönemsellik', 'Ayrıntılı olma ilkesi', 'Önceden izin ilkesi ve yasama onayı'], 'Birlik ilkesi, parlamentonun kamu maliyesinin bütününü tek bakışta görebilmesi için tüm gelir ve giderlerin aynı bütçede yer almasını ister.'),
  ('Bütçenin belirli bir dönem, genellikle bir yıl için hazırlanıp onaylanmasını öngören ilke parlamento açısından neden önemlidir?', 'Yasamanın yürütmeyi düzenli aralıklarla denetleyebilmesini sağlar', ['Hükümetin harcamalarını süresiz ve denetimsiz yapabilmesini sağlar', 'Vergi oranlarının hiçbir zaman değişmemesini güvenceye alır', 'Merkez bankasının bütçeyi onaylamasını zorunlu kılar'], 'Yıllık bütçe, harcama yetkisinin her yıl yenilenmesini gerektirir; böylece parlamento yürütmenin mali tasarruflarını periyodik olarak gözden geçirir.'),
  ('Halkın temsilcilerinin vergi ve harcamalara izin verme yetkisini anlatan \'bütçe hakkı\'nın tarihsel kökleri en çok hangi belgeyle ilişkilendirilir?', 'Magna Carta', ['Ulusların Zenginliği', 'Komünist Manifesto', 'Westphalia Barışı ve sınır antlaşmaları'], '1215 tarihli Magna Carta, kralın genel meclisin onayı olmadan bazı vergiler toplayamayacağı ilkesini getirerek bütçe hakkının ilk adımlarından biri sayılır.'),
  ('Bir mali yılın sonunda bütçenin nasıl uygulandığını, yani gerçekleşen gelir ve giderleri gösteren ve TBMM\'ye sunulan kanun hangisidir?', 'Kesin hesap kanunu', ['Ek bütçe kanunu', 'Torba kanun', 'Orta vadeli program ve mali plan'], 'Kesin hesap kanunu bütçenin uygulama sonuçlarını gösterir; TBMM bu sayede yürütmenin bütçe yetkisini nasıl kullandığını denetler.'),
  ('Bütçe yılı içinde öngörülmeyen ihtiyaçlar nedeniyle mevcut ödeneklerin yetersiz kalması hâlinde çıkarılan bütçeye ne ad verilir?', 'Ek bütçe', ['Kesin hesap', 'Geçici bütçe', 'Kalem bütçe ve ayrıntılı cetvel'], 'Ek bütçe, yıl içinde ortaya çıkan zorunlu harcamalar için yasama organından ek ödenek alınmasını sağlar.'),
  ('Türkiye\'de üç yıllık makroekonomik çerçeveyi ve bütçe hazırlığına esas teşkil eden temel hedefleri belirleyen ve her yıl yenilenen belge hangisidir?', 'Orta Vadeli Program', ['Kesin hesap kanunu', 'Enflasyon raporu ve para programı', 'Yatırım teşvik belgesi'], 'Orta Vadeli Program büyüme, enflasyon ve bütçe hedeflerini üç yıllık bir dönem için ortaya koyar; bütçe çağrısı ve teklifi bu çerçeveye göre hazırlanır.'),
  ('Ödeneklerin personel, mal-hizmet alımı, kira gibi harcama kalemlerine göre ayrıldığı ve denetimin daha çok harcamanın usule uygunluğuna odaklandığı geleneksel bütçe türü hangisidir?', 'Klasik (kalem) bütçe', ['Sıfır tabanlı bütçe', 'Program bütçe', 'Performans esaslı bütçe ve çıktı ölçümü'], 'Klasik bütçede vurgu \'neye ne kadar harcandığı\'dır; harcamaların hangi sonucu ürettiği ikinci plandadır.'),
  ('Bir kamu kurumunun bütçesinin her yıl, önceki yılın ödeneklerine belirli bir oran eklenerek hazırlanması hangi yaklaşımı yansıtır?', 'Artımsal bütçeleme', ['Sıfır tabanlı bütçeleme', 'Performans esaslı bütçeleme', 'Planlama-programlama-bütçeleme sistemi ve çok yıllı analiz'], 'Artımsal bütçelemede geçmiş ödenekler taban kabul edilir ve yalnızca artışlar tartışılır; uygulaması kolaydır ama verimsizliği kalıcılaştırabilir.'),
  ('Kamu harcamalarının eğitim, sağlık, savunma ve kamu düzeni gibi devletin üstlendiği görevlere göre gruplandırılması hangi sınıflandırmadır?', 'Fonksiyonel sınıflandırma', ['Kurumsal sınıflandırma ve idari yapı', 'Ekonomik sınıflandırma', 'Finansman tipi sınıflandırması'], 'Fonksiyonel sınıflandırma harcamanın hangi kamu hizmeti için yapıldığını gösterir; uluslararası karşılaştırmalarda COFOG sınıflaması kullanılır.'),
  ('Bütçede faiz ödemeleri, personel giderleri ve sosyal güvenlik transferleri gibi kısa vadede değiştirilmesi güç kalemlerin payının yüksek olması maliye politikası açısından hangi sorunu doğurur?', 'Bütçe esnekliği azalır', ['Bütçe esnekliği sınırsız biçimde artar', 'Vergi gelirleri kendiliğinden ikiye katlanır', 'Merkez bankası bağımsızlığı yasal olarak kalkar'], 'Zorunlu harcamaların ağırlığı arttıkça hükümetin şoklara karşı harcamaları yeniden düzenleme alanı daralır; buna bütçe katılığı denir.'),
  ('Bir ülkede faiz giderlerinin vergi gelirlerine oranının yıllar içinde yükselmesi neye işaret eder?', 'Vergilerin giderek daha büyük kısmının borç faizine gittiğine', ['Kamu borcunun tamamen ödendiğine', 'Kamu yatırımlarının hızla arttığına', 'Merkez bankasının bütçeye kaynak aktardığına ve faizin sıfıra indiğine'], 'Bu oran arttıkça vergi gelirlerinin eğitim, sağlık ya da yatırım yerine faiz ödemesine ayrılan kısmı büyür; mali alan daralır.'),
  ('Kamu harcamalarını \'reel (kaynak kullanan) harcamalar\' ve \'transfer harcamaları\' olarak ikiye ayıran yaklaşımda reel harcamanın ayırt edici özelliği hangisidir?', 'Devletin karşılığında mal ya da hizmet alması', ['Hiçbir zaman bütçeye yazılmaması', 'Yalnızca dış borç faizlerinden oluşması', 'Yalnızca yerel yönetimlerce yapılabilmesi'], 'Reel harcamada devlet ekonominin kaynaklarını doğrudan kullanır, örneğin öğretmen maaşı ya da yol inşaatı; transferlerde ise karşılıksız gelir aktarımı vardır.'),
  ('Devletin kamu iktisadi teşebbüslerinden aldığı kâr payları ve kamu mallarının kira gelirleri gibi gelirler genel olarak hangi grupta yer alır?', 'Vergi dışı gelirler', ['Dolaysız vergiler', 'Dolaylı vergiler ve harçlar', 'Sosyal güvenlik primleri'], 'Devletin mülkiyetinden ve girişimlerinden doğan gelirler, cebri olmadıkları için vergi dışı gelirler arasında sınıflandırılır.'),
  ('Bir hükümetin bütçe açığını kamuya ait şirketlerin hisselerini satarak kapatmasıyla ilgili en doğru değerlendirme hangisidir?', 'Tek seferlik bir gelirdir; kalıcı açığı çözmez', ['Kalıcı ve her yıl tekrarlanan bir vergi geliri yaratır', 'Açığı merkez bankası parası basmaya dönüştürür', 'Kamu borcunu otomatik olarak iki katına çıkarır'], 'Özelleştirme gelirleri bir defalıktır ve varlık satışıdır; harcama-gelir arasındaki yapısal açık sürerse sorun geri döner.'),
  ('Bütçe açığının yurt dışından döviz cinsinden borçlanarak finanse edilmesinin iç borçlanmaya göre özel riski hangisidir?', 'Kur riski', ['Faiz oranının her zaman sıfır olması', 'Borcun asla geri ödenmemesi', 'Vergi gelirlerinin yasal olarak dövize bağlanması ve tahsil edilememesi'], 'Ulusal para değer kaybederse döviz borcunun yerel para karşılığı artar; borç yükü vergi gelirlerine göre hızla büyüyebilir.'),
  ('Bir hükümetin açığını yurt içi bankalardan yüksek faizle borçlanarak kapatması, bankaların reel sektöre kredi vermek yerine devlet tahvili almasına yol açıyor. Bu durum hangi kavramla açıklanır?', 'Dışlama etkisinin kredi piyasası üzerinden işlemesi', ['Ricardocu denkliğin tam geçerliliği', 'Otomatik istikrarlandırıcıların güçlenmesi', 'Para yanılsaması ve nominal katılık'], 'Kamu kâğıtları güvenli ve getirili olunca bankalar özel kesime daha az kredi verir; özel yatırım finansman bulmakta zorlanır.'),
  ('Bazı petrol ihracatçısı ülkelerin bütçe gelirlerinin büyük kısmının ham petrol satışlarından gelmesi maliye politikası için hangi riski taşır?', 'Gelirlerin emtia fiyatlarıyla sert dalgalanması', ['Vergi gelirlerinin sabit ve tahmin edilebilir olması', 'Bütçe açığının hiçbir koşulda oluşamaması', 'Kamu harcamalarının sıfırlanmak zorunda kalması ve devletin küçülmesi'], 'Petrol fiyatı düştüğünde gelirler çöker; bu nedenle birçok ülke gelir istikrarı için emtia fonları ve mali kurallar kullanır.'),
  ('Bir hükümet bütçe açığını kapatmak için vergileri artırmak yerine borçlanmayı seçerse vergi yükünün zamana yayılması bakımından ne olur?', 'Yük gelecekteki vergi mükelleflerine kayar', ['Yük tamamen ortadan kalkar', 'Yük yalnızca merkez bankasına geçer', 'Yük yalnızca yabancı ülkelerin vatandaşlarına yansır'], 'Borç gelecekte faiziyle ödeneceği için bugünkü harcamanın finansman yükü gelecekteki vergi ödeyicilere ertelenmiş olur.'),
  ('Borç oranındaki değişim yaklaşık olarak Δd = (r − g)·d − s formülüyle verilir. Borç/GSYH oranı yüzde 60, reel faiz yüzde 5, reel büyüme yüzde 3 ve faiz dışı denge sıfırsa borç oranı bir yılda yaklaşık kaç puan değişir?', '1,2 puan artar', ['1,2 puan azalır', '3 puan artar', 'Hiç değişmez çünkü faiz dışı denge sıfırdır'], 'Δd = (0,05 − 0,03) × 60 − 0 = 1,2. Faiz büyümeden yüksek olduğu için faiz dışı denge sıfırken bile oran yükselir.'),
  ('Reel faizin yüzde 2, reel büyümenin yüzde 4 olduğu ve faiz dışı dengenin sıfır olduğu bir ekonomide borç/GSYH oranı yüzde 80\'dir. Δd = (r − g)·d − s yaklaşımına göre oran bir yılda nasıl değişir?', 'Yaklaşık 1,6 puan azalır', ['Yaklaşık 1,6 puan artar', 'Yaklaşık 6 puan azalır', 'Değişmez çünkü bütçe dengededir'], 'Δd = (0,02 − 0,04) × 80 = −1,6. Büyüme faizden yüksekse borç oranı faiz dışı açık olmasa da kendiliğinden geriler.'),
  ('Borç oranını sabit tutmak için gereken faiz dışı fazla s = (i − g)·d ile yaklaşık hesaplanıyor. Nominal faiz yüzde 10, nominal büyüme yüzde 6 ve borç/GSYH oranı yüzde 50 ise gereken faiz dışı fazla GSYH\'nin yaklaşık yüzde kaçıdır?', '2', ['4', '5', '0,4'], 's = (0,10 − 0,06) × 50 = 2. Ülkenin GSYH\'nin yaklaşık yüzde 2\'si kadar faiz dışı fazla vermesi gerekir.'),
  ('Kamu borcunun milli gelire oranının yüksek olmasının ekonomiye olası maliyetlerinden biri aşağıdakilerden hangisidir?', 'Faiz yükünün kamu yatırımı ve sosyal harcamalar için ayrılan alanı daraltması', ['Para arzının kendiliğinden ve kalıcı olarak sıfırlanması, böylece bankacılık sisteminin kredi verememesi', 'Döviz kurunun yasal olarak sabitlenmesi', 'Vergi oranlarının kendiliğinden düşmesi'], 'Yüksek borç, faiz harcamalarını büyütür; ayrıca risk primini artırarak özel kesimin borçlanma maliyetini de yükseltebilir.'),
  ('Hazine\'nin bir yıl içinde yaptığı iç borçlanmanın aynı yılki iç borç ödemelerine oranına ne ad verilir?', 'İç borç çevirme oranı', ['Borç/GSYH oranı', 'Faiz dışı denge oranı', 'Kamu yatırımlarının bütçe içindeki payı'], 'Çevirme oranı yüzde 100\'ün üzerindeyse Hazine vadesi gelen borçtan fazlasını yeniden borçlanıyordur; altındaysa net borç ödemesi yapıyordur.'),
  ('Hazine bir yılda 1.200 milyar lira iç borç servisi yaparken aynı yıl 1.080 milyar lira iç borçlanma gerçekleştirmiştir. Çevirme oranı yüzde kaçtır?', '90', ['111', '120', '108'], 'Çevirme oranı = 1.080 / 1.200 = 0,90, yani yüzde 90. Hazine vadesi gelen borcun bir kısmını borçlanma dışındaki kaynaklarla ödemiştir.'),
  ('Hazine\'nin 2012\'den itibaren klasik tahvillerin yanında faizsiz finans ilkelerine uygun kira sertifikası da ihraç etmesinin borç yönetimi açısından temel gerekçesi hangisidir?', 'Yatırımcı tabanını genişletip faiz hassasiyeti olan tasarrufları çekmek', ['Kamu borcunu faiz ödemeden ve hiçbir maliyet üstlenmeden kalıcı olarak silmek', 'Borçlanmayı tamamen dövize kaydırmak', 'Merkez bankasının politika faizini belirlemek'], 'Kira sertifikaları, faizli araçlara yatırım yapmak istemeyen kesimlerin tasarruflarını da kamu finansmanına çekerek borçlanma kaynaklarını çeşitlendirir.'),
  ('Borç yönetiminde borcun ortalama vadesinin uzatılmasının temel amacı hangisidir?', 'Yeniden finansman riskini azaltmak', ['Faiz ödemelerini her durumda sıfırlamak ve borcu silmek', 'Kur riskini artırmak', 'Bütçe açığını yasal olarak yasaklamak'], 'Vade kısa olunca borcun büyük bölümü sık sık yeniden çevrilir; piyasa koşulları kötüleşirse bu çevirme pahalı ya da imkânsız hâle gelebilir.'),
  ('Kamu borcunun büyük kısmının değişken faizli ya da kısa vadeli olması bir faiz şokunda bütçeyi nasıl etkiler?', 'Faiz giderleri hızla artar', ['Faiz giderleri hemen düşer', 'Bütçe hiçbir biçimde etkilenmez', 'Vergi gelirleri kendiliğinden faiz kadar artar ve açık kapanır'], 'Değişken faizli ya da sık çevrilen borçta piyasa faizindeki artış kısa sürede borç servisine yansır; bu faiz riskidir.'),
  ('Avro bölgesinde üye ülkelerin bütçe disiplinini Maastricht sonrasında da sürdürmesini amaçlayan ve 1997\'de kabul edilen düzenleme hangisidir?', 'İstikrar ve Büyüme Paktı', ['Schengen Antlaşması', 'Lizbon Antlaşması', 'Roma Antlaşması ve Avrupa Ekonomik Topluluğu\'nun kuruluşu'], 'İstikrar ve Büyüme Paktı, yüzde 3 açık ve yüzde 60 borç sınırlarının uygulanmasını, aşılması durumunda aşırı açık prosedürünü düzenler.'),
  ('İstikrar ve Büyüme Paktı\'nda bir ülkenin bütçe açığı yüzde 3 sınırını aşınca başlatılan ve düzeltici önlem takvimi içeren süreç hangisidir?', 'Aşırı açık prosedürü', ['Avrupa Sömestri başlangıç bildirimi', 'Yakınsama raporu ve avroya geçiş değerlendirmesi', 'Bankacılık birliği denetimi'], 'Aşırı açık prosedürüyle Komisyon ve Konsey ülkeden belirli bir sürede açığı düzeltmesini ister; uyulmazsa yaptırımlar gündeme gelebilir.'),
  ('Kamu yatırımlarının borçla finanse edilmesine izin verip cari harcamaların vergilerle karşılanmasını öngören mali kurala ne ad verilir?', 'Altın kural', ['Taylor kuralı', 'Gümüş standart', 'Borç tavanı ve harcama dondurması'], 'Altın kurala göre gelecek kuşaklara da fayda sağlayan yatırımların maliyeti borçla zamana yayılabilir; cari harcamalar ise bugünkü vergilerle karşılanmalıdır.'),
  ('Mali kuralların uygulanmasını ve hükümetin bütçe tahminlerini bağımsız olarak değerlendiren kurumlara ne ad verilir?', 'Bağımsız mali konseyler', ['Merkez bankası para politikası kurulları', 'Vergi mahkemeleri', 'Ticaret odaları ve sanayi birlikleri'], 'Mali konseyler hükümetin tahminlerinin gerçekçiliğini ve kurallara uyumu bağımsız olarak değerlendirerek mali disiplini destekler.'),
  ('Bir mali kuralın \'kaçış maddesi\' içermesinin amacı hangisidir?', 'Doğal afet ya da derin resesyon gibi olağanüstü durumlarda kuralın geçici olarak askıya alınabilmesi', ['Kuralın hiçbir koşulda uygulanmamasını ve yalnızca kâğıt üzerinde kalmasını güvenceye almak', 'Hükümetin her yıl kuralı değiştirebilmesi', 'Merkez bankasının bütçeyi onaylaması'], 'Kaçış maddeleri, kuralın katılığının olağanüstü şoklarda zarar vermesini önler; genellikle açıkça tanımlanmış koşullara ve sonrasında uyum planına bağlanır.'),
  ('Katı mali kuralların sıkça eleştirilen bir yan etkisi aşağıdakilerden hangisidir?', 'Hükümetlerin kuralı dolanmak için yaratıcı muhasebe ya da bütçe dışı işlemlere yönelmesi', ['Kamu harcamalarının denetiminin tamamen kolaylaşması', 'Vergi kaçakçılığının ve kayıt dışı ekonominin kendiliğinden ve kısa sürede tamamen ortadan kalkması', 'Para politikasının etkisiz kalması'], 'Kurala uymak siyasi olarak zorlaşınca harcamalar bütçe dışı kurumlara kaydırılabilir ya da tek seferlik önlemlere başvurulabilir; bu da şeffaflığı azaltır.'),
  ('Bir vergi tarifesinde ilk 50.000 lira vergiden muaf, 50.000–150.000 lira arası yüzde 20, 150.000 liranın üzeri yüzde 40 oranında vergilendiriliyor. Yıllık geliri 200.000 lira olan kişinin ortalama vergi oranı yüzde kaçtır?', '20', ['40', '30', '10'], 'Vergi = 100.000 × 0,20 + 50.000 × 0,40 = 20.000 + 20.000 = 40.000 lira. Ortalama oran 40.000 / 200.000 = yüzde 20; marjinal oran ise yüzde 40\'tır.'),
  ('Artan oranlı bir gelir vergisi tarifesinde, en alt dilimin üzerindeki bir mükellef için ortalama ve marjinal vergi oranları arasındaki ilişki nasıldır?', 'Marjinal oran ortalama orandan yüksektir', ['Ortalama oran her zaman marjinal orandan daha yüksektir', 'İkisi her zaman birbirine eşittir', 'Marjinal oran her zaman sıfırdır'], 'Üst dilimlerdeki gelir daha yüksek oranla vergilendirildiğinden son liraya uygulanan oran, tüm gelirin ortalamasından büyüktür.'),
  ('Kişilerin çalışma, tasarruf ve yatırım kararlarını en çok hangi vergi oranı etkiler?', 'Marjinal vergi oranı', ['Ortalama vergi oranı', 'Geçmiş yılların ortalama oranı', 'Toplam vergi gelirinin GSYH\'ye oranı ve kamu kesimi büyüklüğü'], 'Bir saat fazla çalışmak ya da ek yatırım yapmak, ek kazancın ne kadarının elde kalacağına bağlıdır; bunu marjinal oran belirler.'),
  ('Bir işverenin bir çalışana toplam maliyeti 10.000 lira, çalışanın eline geçen net ücret 6.000 liradır. Gelir vergisi ve sosyal güvenlik primlerinden oluşan vergi kaması toplam işgücü maliyetinin yüzde kaçıdır?', '40', ['60', '67', '4,5'], 'Vergi kaması = (10.000 − 6.000) / 10.000 = yüzde 40. Kama büyüdükçe kayıtlı istihdamın maliyeti artar.'),
  ('Akaryakıttan alınan vergilerin karayolu yapım ve bakımına ayrılması hangi vergi adaleti ilkesine dayanır?', 'Fayda ilkesi', ['Ödeme gücü ilkesi', 'Eşit marjinal fedakârlık ilkesi', 'Genellik ilkesi ve evrensellik'], 'Fayda ilkesine göre kamu hizmetinden yararlananlar bedelini ödemelidir; yolları kullananlar akaryakıt vergisiyle bu hizmeti finanse eder.'),
  ('Fayda ilkesinin bütün kamu harcamalarının finansmanında temel ölçüt olarak kullanılamamasının başlıca nedeni hangisidir?', 'Savunma gibi kamusal mallardan kimin ne kadar yararlandığının ölçülememesi', ['Kamu hizmetlerinden yalnızca yabancıların yararlanması', 'Fayda ilkesinin vergi kanunlarında yasaklanmış olması', 'Bu ilkenin her zaman zenginleri koruması ve yoksullardan orantısız biçimde çok vergi alınmasına yol açması'], 'Saf kamusal mallarda bireysel faydayı ölçmek ve dışlama yapmak mümkün değildir; ayrıca sosyal yardım gibi transferler fayda ilkesiyle finanse edilemez.'),
  ('Geliri daha yüksek olanların daha fazla vergi ödemesi gerektiğini savunan \'dikey adalet\' ilkesi hangi yaklaşımın sonucudur?', 'Ödeme gücü yaklaşımı', ['Fayda yaklaşımı', 'Vergi rekabeti yaklaşımı', 'Götürü vergi yaklaşımı ve kişi başı eşit vergi'], 'Ödeme gücü yaklaşımı vergiyi kişinin mali gücüne bağlar; buradan farklı güçteki kişilerin farklı vergi ödemesi gerektiği, yani dikey adalet çıkar.'),
  ('Asgari geçim indirimi ya da vergiden muaf bir alt gelir sınırı uygulanmasının ödeme gücü ilkesi açısından gerekçesi hangisidir?', 'Zorunlu ihtiyaçları karşılayacak gelirin vergi ödeme gücü yaratmaması', ['Düşük gelirlilerin kamu hizmetlerinden hiç yararlanmaması', 'Vergi idaresinin yalnızca zenginleri denetleyebilmesi', 'Düşük gelirlerin tamamının kayıt dışı olduğunun kanunla kabul edilmiş ve belgelenmiş olması'], 'Ödeme gücü, temel yaşam ihtiyaçlarını aşan gelirle başlar; bu nedenle asgari yaşam düzeyine karşılık gelen gelir vergi dışı tutulur.'),
  ('Milton Friedman\'ın 1962 tarihli \'Kapitalizm ve Özgürlük\' kitabında yoksullukla mücadele için önerdiği, belirli bir gelirin altındakilere devletin ödeme yaptığı sistem hangisidir?', 'Negatif gelir vergisi', ['Artan oranlı servet vergisi', 'Asgari ücretin kaldırılıp yerine kota konması', 'Katma değer vergisi ve tüketim vergisi'], 'Negatif gelir vergisinde belirli bir eşiğin altındaki kişiler vergi ödemek yerine devletten gelir alır; eşik aşıldıkça ödeme azalır.'),
  ('Negatif gelir vergisi sisteminde garanti gelir 12.000 lira, kesinti oranı yüzde 50\'dir. Kendi kazancı 8.000 lira olan bir kişinin devletten alacağı ödeme kaç liradır?', '8.000', ['12.000', '4.000', '16.000'], 'Ödeme = 12.000 − 0,5 × 8.000 = 8.000 lira. Kişinin toplam geliri 16.000 lira olur.'),
  ('Negatif gelir vergisinin, geliri belirli bir sınırı aşan herkesin yardımını tamamen kesen sosyal yardım programlarına göre üstünlüğü hangisidir?', 'Kazanç arttıkça yardım kademeli azaldığı için çalışma güdüsünü daha az bozması', ['Hiçbir kamu maliyeti doğurmaması ve bütçeye herhangi bir yük getirmeden yoksulluğu tamamen ortadan kaldırması', 'Yalnızca çalışmayan kişilere ödeme yapması', 'Kesinti oranının yüzde 100 olması'], 'Yardım bir eşikte tamamen kesilirse ek kazanç toplam geliri düşürebilir; kademeli kesinti ise çalışmanın her zaman geliri artırmasını sağlar.'),
  ('Belirli faaliyetleri teşvik etmek amacıyla tanınan istisna, muafiyet ve indirimler nedeniyle devletin vazgeçtiği vergi gelirine ne ad verilir?', 'Vergi harcaması', ['Vergi ziyaı', 'Vergi kaçakçılığı', 'Ölü ağırlık kaybı ve verimlilik kaybı'], 'Vergi harcamaları doğrudan bütçe harcaması gibi kaynak aktarır ama bütçede gider olarak görünmez; bu nedenle şeffaflık açısından ayrıca raporlanmaları önerilir.'),
  ('Almanya\'nın 2020\'nin ikinci yarısında KDV oranını geçici olarak yüzde 19\'dan yüzde 16\'ya indirmesinin tüketiciler üzerindeki amaçlanan etkisi hangisidir?', 'Dayanıklı mal alımlarını indirim dönemine çekmek', ['Tüketimi kalıcı olarak azaltmak ve tasarrufu artırmak', 'Vergi gelirlerini artırmak', 'İthalatı yasaklamak ve yerli üretimi korumak'], 'Geçici indirim, fiyatların ileride yeniden yükseleceğini bilen tüketicileri özellikle büyük alımlarını öne çekmeye teşvik eder; bu bir \'zamanlama\' etkisidir.'),
  ('Arz yönlü iktisat maliye politikasında öncelikle neyi savunur?', 'Marjinal vergi oranlarını düşürerek üretim güdülerini güçlendirmeyi', ['Kamu harcamalarını artırarak ve bütçe açığı vererek toplam talebi yükseltmeyi', 'Para arzını sabit bir oranda büyütmeyi', 'Gümrük vergilerini artırarak ithalatı tamamen durdurmayı'], 'Arz yönlü yaklaşım, vergilerin teşvikler üzerindeki etkisini öne çıkarır; düşük marjinal oranların potansiyel üretimi artıracağını savunur.'),
  ('\'Damlama\' (trickle-down) ekonomisi eleştirisi hangi iddiayı hedef alır?', 'Zenginlere yapılan vergi indiriminin yatırım yoluyla herkese yayılacağı iddiasını', ['Merkez bankasının faiz indirimlerinin enflasyonu kısa sürede ve kalıcı olarak düşüreceği iddiasını', 'Gümrük vergilerinin yerli sanayiyi koruyacağı iddiasını', 'Kamu borcunun gelecek kuşaklara yük olmayacağı iddiasını'], 'Eleştirmenler, zenginlere yönelik indirimlerin büyük kısmının tasarrufa ve varlık fiyatlarına gittiğini, alt gelir gruplarına yansımanın sınırlı kaldığını savunur.'),
  ('İtalyan maliyeci Amilcare Puviani\'nin ortaya koyduğu \'mali yanılsama\' kavramı neyi anlatır?', 'Vergilerin yükünün vatandaşlarca olduğundan düşük algılanmasını', ['Kamu harcamalarının bütçede iki kez yazılması ve bu yüzden toplam harcamanın şişmesi', 'Vergi oranlarının her yıl otomatik olarak düşmesi', 'Hükümetin bütçeyi hiç yayımlamaması'], 'Dolaylı vergiler, stopaj ve borçla finansman gibi yöntemler vergi yükünü daha az görünür kılar; vatandaşlar kamu hizmetlerinin maliyetini olduğundan düşük algılar.'),
  ('Mali yanılsama açısından aşağıdaki finansman yöntemlerinden hangisi vatandaşlarca en az fark edilen yöntem olma eğilimindedir?', 'Fiyatların içine gizlenmiş dolaylı vergiler', ['Her yıl ayrıca beyan edilip ödenen servet vergisi', 'Kişi başına eşit ve elden ödenen götürü vergi', 'Yıllık beyanla ödenen gelir vergisi'], 'Fiyata dâhil vergiler tüketicinin ayrıca ödediği bir tutar gibi algılanmadığından, doğrudan ödenen vergilere göre daha az görünürdür.'),
  ('Zengin ve yoksul bölgeler arasındaki vergi kapasitesi farklarını gidermek için merkezi yönetimin yoksul bölgelere daha fazla kaynak aktarmasına ne ad verilir?', 'Mali denkleştirme (eşitleme) transferi', ['Şartlı eşleştirme yardımı', 'Vergi rekabeti', 'Senyoraj ve para basma geliri aktarımı'], 'Denkleştirme transferleri, yerel yönetimlerin benzer vergi yükleriyle benzer kalitede hizmet sunabilmesini amaçlar; Almanya ve Kanada\'da yaygındır.'),
  ('Modern Para Teorisi\'ne (MMT) göre kendi parasını basan bir devletin harcamalarının asıl sınırı nedir?', 'Enflasyon', ['Altın rezervlerinin miktarı', 'Vergi gelirlerinin nominal tutarı', 'Dış ticaret fazlasının büyüklüğü ve döviz rezervleri'], 'MMT, kendi para birimiyle borçlanan devletin nominal olarak ödeme güçlüğüne düşmeyeceğini; reel kaynak sınırının aşılmasıyla ortaya çıkan enflasyonun asıl kısıt olduğunu savunur.'),
  ('Avrupa Birliği\'nin Covid-19 sonrası toparlanma için 2020\'de üzerinde uzlaştığı ve AB adına ortak borçlanmayla finanse edilen programın adı nedir?', 'NextGenerationEU', ['Marshall Planı', 'Lizbon Stratejisi', 'Avrupa Sömestri ve istikrar programı'], 'NextGenerationEU, Avrupa Komisyonu\'nun piyasalardan büyük ölçekli ortak borçlanmasıyla finanse edilen yaklaşık 750 milyar avroluk bir toparlanma aracıdır.'),
  ('2001 krizinin ardından Türkiye\'de uygulanan programın temel mali hedeflerinden biri hangisidir?', 'Yüksek faiz dışı fazla vererek kamu borcunu düşürmek', ['Kamu harcamalarını hızla artırıp açığı bilinçli olarak büyütmek', 'Merkez bankasının bütçeyi doğrudan finanse etmesi', 'Bütün vergileri geçici olarak kaldırmak'], 'Program, GSMH\'nin yaklaşık yüzde 6,5\'i düzeyinde faiz dışı fazla hedefleyerek borç dinamiğini kontrol altına almayı amaçladı.'),
  ('Japonya\'nın 1990\'larda varlık balonunun çökmesinden sonra art arda açıkladığı büyük kamu yatırımı paketlerinin uzun vadeli mali sonucu hangisidir?', 'Borç/GSYH oranının gelişmiş ülkelerin en yükseklerine çıkması', ['Kamu borcunun tamamen ödenmesi', 'Bütçenin sürekli fazla vermesi', 'Vergi gelirlerinin iki katına çıkması ve kamu borcunun birkaç yıl içinde sıfırlanması'], 'Tekrarlanan teşvik paketleri ve düşük büyüme, Japonya\'nın brüt kamu borcunun GSYH\'nin iki katını aşmasına yol açtı.'),
  ('Yunanistan\'ın 2010 sonrasında aldığı kurtarma paketlerine bağlanan koşulların genel niteliği hangisidir?', 'Sert mali konsolidasyon ve yapısal reformlar', ['Sınırsız kamu harcaması artışı ve vergi indirimleri', 'Drahmiye dönülmesi ve kendi parasını basması', 'Merkez bankasının bütçeyi finanse etmesi'], 'Troyka (AB Komisyonu, AMB ve IMF) programları harcama kesintileri, vergi artışları, emeklilik ve işgücü piyasası reformlarını şart koştu; ekonomi bu dönemde derin bir daralma yaşadı.'),
  ('Covid-19 döneminde birçok Avrupa ülkesinin işten çıkarma yerine çalışma saatlerinin kısaltılıp ücret kaybının devletçe karşılanmasını sağlayan programları genişletmesi hangi aracın örneğidir?', 'Kısa çalışma ödeneği', ['İşsizlik sigortasının kaldırılması', 'Asgari ücretin dondurulması ve düşürülmesi', 'Gümrük vergisi indirimi'], 'Almanya\'daki Kurzarbeit örneğinde olduğu gibi kısa çalışma ödenekleri işçi-işveren bağını koruyarak toparlanmada istihdamın hızla geri dönmesini sağlar.'),
  ('Bir hükümetin derin bir resesyonda altyapı yatırımı yerine doğrudan hanehalkı transferlerini tercih etmesinin başlıca gerekçesi hangisidir?', 'Transferlerin çok daha hızlı uygulanabilmesi', ['Transferlerin hiçbir maliyet doğurmaması', 'Altyapı yatırımlarının toplam talebi hiç etkilememesi', 'Transferlerin yasa gerektirmeden merkez bankasınca ödenmesi ve bütçeye yansımaması'], 'Altyapı projeleri planlama ve ihale nedeniyle gecikir; transferler ise mevcut kanallarla haftalar içinde hanehalklarına ulaşabilir.'),
  ('ABD Merkez Bankası FOMC üyelerinin gelecek yıllar için uygun gördükleri politika faizi düzeylerini noktalarla gösterdiği ve 2012\'den beri yayımladığı grafik hangi adla bilinir?', 'Nokta grafiği', ['Phillips eğrisi', 'Laffer eğrisi', 'Getiri eğrisi ve vade yapısı'], 'Nokta grafiği her FOMC üyesinin faiz tahminini anonim olarak gösterir; piyasalar bu grafikten olası faiz patikasını çıkarmaya çalışır.'),
  ('Merkez bankasının \'faizler en az 2015 ortasına kadar sıfıra yakın kalacak\' gibi belirli bir tarih vererek yaptığı açıklama hangi yönlendirme türüdür?', 'Takvime bağlı yönlendirme', ['Eşik temelli yönlendirme', 'Kur çapası', 'Parasal hedef ve para programı'], 'Takvime bağlı yönlendirmede politika patikası belirli bir tarihe bağlanır; açık olmakla birlikte koşullar değiştiğinde esneklik sorunu doğurabilir.'),
  ('Merkez bankası para politikası kurulu toplantı özetlerini kısa süre sonra yayımlamaya başladığında beklenen fayda hangisidir?', 'Piyasaların karar gerekçesini anlayıp beklentilerini daha isabetli oluşturması', ['Faiz kararlarının hükümet tarafından onaylanmasının hızlanması ve meclise sunulması', 'Bankaların zorunlu karşılık oranlarının kendiliğinden düşmesi', 'Bütçe açığının kendiliğinden küçülmesi'], 'Şeffaflık, merkez bankasının tepki fonksiyonunu öğrenmeyi kolaylaştırır; beklentiler politikayla uyumlu hâle gelir ve sürprizler azalır.'),
  ('Petrol fiyatlarındaki ani bir artış hem enflasyonu yükseltip hem de üretimi düşürdüğünde merkez bankasının karşılaştığı ikilem hangisidir?', 'Faiz artırırsa üretim daha da düşer, indirirse enflasyon daha da artar', ['Faiz değişikliği hem enflasyonu hem üretimi aynı anda ve aynı yönde düzeltir, ödünleşim doğmaz', 'Arz şoklarının para politikasıyla hiçbir ilişkisi yoktur', 'Merkez bankası yasal olarak petrol fiyatını belirlemek zorundadır'], 'Arz şoku enflasyon ile üretimi ters yönlere iter; tek bir faiz aracıyla iki hedefi birlikte düzeltmek mümkün olmaz.'),
  ('Kuraklık nedeniyle gıda fiyatlarının bir kez sert artması, beklentiler sağlam biçimde çapalanmış bir ülkede genellikle nasıl sonuçlanır?', 'Yıllık enflasyon geçici olarak yükselir, sonra baz etkisiyle geriler', ['Enflasyon kalıcı olarak ve her yıl bir öncekinden daha fazla artarak yükselir', 'Fiyatlar hiç değişmez', 'Deflasyon başlar ve işsizlik sıfırlanır'], 'Tek seferlik fiyat düzeyi şoku, ikinci tur etkiler sınırlıysa yıllık enflasyonu yalnızca bir süre yükseltir; on iki ay sonra karşılaştırma tabanı değişir.'),
  ('1970\'lerdeki petrol şoklarına birçok merkez bankasının gevşek para politikasıyla uyum sağlamasının sonucu genel olarak nasıl değerlendirilir?', 'Beklentileri yükseltip enflasyonu kalıcılaştırdığı', ['Enflasyonun hemen sıfıra inmesini sağladığı', 'İşsizliği kalıcı olarak ortadan kaldırdığı', 'Petrol fiyatlarını düşürdüğü ve şokları kısa sürede tamamen geri çevirdiği'], 'Uyumlu politika üretim kaybını kısa vadede sınırladı ama ücret-fiyat sarmalı başladı; sonuçta 1980\'lerin başında çok maliyetli bir dezenflasyon gerekti.'),
  ('Uzun vadeli nominal devlet tahvili faizi yüzde 4,5, aynı vadeli enflasyona endeksli tahvilin reel faizi yüzde 2 ise piyasanın ima ettiği yıllık enflasyon beklentisi (başabaş enflasyonu) yaklaşık yüzde kaçtır?', '2,5', ['6,5', '2,0', '4,50'], 'Başabaş enflasyonu ≈ nominal faiz − reel faiz = 4,5 − 2 = 2,5. Merkez bankaları bu göstergeyi beklentilerin çapalanıp çapalanmadığını izlemek için kullanır.'),
  ('Negatif politika faizlerine yöneltilen başlıca eleştirilerden biri hangisidir?', 'Bankaların faiz marjlarının daralması', ['Kredi faizlerini yasal olarak yükseltmesi', 'Tasarruf sahiplerinin faiz gelirini her durumda artırması', 'Merkez bankasının para basmasını tamamen engellemesi'], 'Bankalar küçük mevduat sahiplerine negatif faiz uygulamakta zorlandığından net faiz marjları daralır; bu da kredi arzını olumsuz etkileyebilir.'),
  ('Bir merkez bankasının politika faizini düşük tutarken konut kredilerinde borç/gelir oranına sınır getirmesi hangi politika bileşimine örnektir?', 'Para politikası ile makroihtiyati politikanın birlikte kullanılması', ['Maliye politikasının para politikasının yerini alması ve faizin yasayla sabitlenmesi', 'Kur çapasının yeniden benimsenmesi', 'Niceliksel sıkılaştırma ve tahvil satışı'], 'Faiz genel talep ve enflasyon için ayarlanırken hedefli makroihtiyati araçlar belirli kesimlerdeki risk birikimini sınırlar; böylece iki hedef için iki araç kullanılır.'),
  ('Hükümetlerin faizleri enflasyonun altında tutup yurt içi tasarrufları kamu borcuna yönlendirerek borcun reel değerini eritmesine ne ad verilir?', 'Finansal baskı', ['Finansal derinleşme', 'Niceliksel sıkılaştırma', 'Mali konsolidasyon ve kemer sıkma'], 'Carmen Reinhart\'ın vurguladığı finansal baskı; faiz tavanları, sermaye kontrolleri ve bankalara kamu kâğıdı tutma zorunluluğu gibi araçlarla negatif reel faiz yaratır.'),
  ('Kamu borcu 500 milyar lira, nominal GSYH 1.000 milyar liradır. Bir yılda hiç yeni borçlanma olmazken yüzde 20 enflasyon ve sıfır reel büyüme nedeniyle nominal GSYH 1.200 milyar liraya çıkarsa borç/GSYH oranı yaklaşık yüzde kaça iner?', '42', ['50', '30', '100'], 'Yeni oran = 500 / 1.200 ≈ 0,417, yani yaklaşık yüzde 42. Beklenmedik enflasyon sabit nominal borcun ekonomiye göre ağırlığını azaltır.'),
  ('Nominal GSYH yüzde 8 artarken vergi gelirleri yüzde 12 artmıştır. Vergi gelirlerinin GSYH\'ye göre esnekliği (vergi kaldıracı) kaçtır?', '1,5', ['0,67', '4', '20,0'], 'Esneklik = vergi gelirindeki yüzde değişim / GSYH\'deki yüzde değişim = 12 / 8 = 1,5. Değerin 1\'den büyük olması vergilerin ekonomiden hızlı büyüdüğünü gösterir.'),
  ('Bir ülkede vergi affı çıkarılıp geçmiş vergi borçlarının cezalarının silinmesine yöneltilen temel eleştiri hangisidir?', 'Düzenli vergi ödeyenlerin uyum güdüsünü zayıflatması', ['Vergi gelirlerini kısa vadede ve kalıcı olarak her zaman azaltması', 'Vergi idaresini tamamen ortadan kaldırması', 'Yalnızca dolaylı vergileri etkilemesi'], 'Sık tekrarlanan aflar, vergisini zamanında ödeyenleri cezalandırır ve \'nasılsa af çıkar\' beklentisi yaratarak gelecekteki uyumu düşürür.'),
  ('Bir hükümetin, mali sürdürülebilirliği ya da piyasa erişimini tehlikeye atmadan ek harcama yapabileceği ya da vergi indirebileceği bütçe kapasitesine ne ad verilir?', 'Mali alan', ['Mali yanılsama', 'Mali baskınlık ve parasal finansman', 'Vergi kaması'], 'Mali alan; borç düzeyi, faiz yükü, büyüme beklentisi ve piyasa güveni gibi etkenlere bağlıdır. Düşük borçlu ülkeler şoklara karşı daha geniş mali alana sahiptir.'),
  ('Devletin bütçede doğrudan gider olarak görünmeyen ama belirli koşullar gerçekleşirse ödemek zorunda kalacağı yükümlülüklere ne ad verilir?', 'Koşullu yükümlülükler', ['Kesinleşmiş faiz ödemeleri', 'Personel giderleri', 'Vadesi gelmiş iç borç anaparası ve kuponları'], 'Kamu garantili krediler, kamu-özel işbirliği projelerindeki gelir garantileri ve olası banka kurtarmaları koşullu yükümlülüklere örnektir.'),
  ('Bir kamu-özel işbirliği projesinde devletin yüklenici firmaya köprüden geçecek araç sayısı için garanti vermesi kamu maliyesi açısından hangi riski doğurur?', 'Trafik gerçekleşmezse aradaki farkın bütçeden ödenmesi riski', ['Köprünün her durumda bedava kullanılması ve gelir elde edilmemesi', 'Vergi gelirlerinin otomatik olarak iki katına çıkması', 'Merkez bankasının köprüyü işletmesi'], 'Garanti edilen talep gerçekleşmezse devlet eksik kalan geliri tamamlamak zorunda kalır; bu, bugünkü bütçede görünmeyen bir koşullu yükümlülüktür.'),
  ('Bolivya\'nın 1985\'te yaşadığı hiperenflasyonu durduran istikrar programının temel unsuru hangisidir?', 'Bütçe açığının sert biçimde kapatılması ve para basımının durdurulması', ['Para basımının hızlandırılması', 'Fiyatların her gün yeniden belirlenmesinin zorunlu hâle getirilmesi', 'Bütün ithalatın yasaklanması ve dış ticaretin devletleştirilerek kamu tekeline verilmesi'], 'Hiperenflasyonun kaynağı açıkların para basılarak finanse edilmesiydi; 1985 programı mali disiplin ve kur birliğiyle enflasyonu birkaç hafta içinde durdurdu.'),
  ('Yalnızca ücret ve fiyat dondurmasına dayanıp bütçe açığını kapatmayan heterodoks programların sık sık başarısız olmasının temel nedeni hangisidir?', 'Enflasyonun asıl kaynağı olan parasal finansman sürdüğü için', ['Dondurmaların fiyatları her zaman düşürmesi', 'Dondurma süresince ekonominin tamamen durması ve kalıcı deflasyon yaşanması', 'Bütçe açığının enflasyonla hiçbir ilişkisi olmaması'], 'Arjantin\'in 1985 Austral Planı ve Brezilya\'nın 1986 Cruzado Planı gibi örneklerde mali uyum zayıf kalınca dondurmalar kalktığında enflasyon geri döndü.'),
  ('Kronik yüksek enflasyon yaşayan ekonomilerde enflasyonun talep baskısı olmasa bile geçmiş enflasyonu izleyerek kendini sürdürmesine ne ad verilir?', 'Ataletli (inersiyal) enflasyon', ['Talep çekişli enflasyon', 'Hiperdeflasyon ve fiyat çöküşü', 'Gizli enflasyon ve kayıt dışı fiyatlama'], 'Ücret, kira ve fiyatların geçmiş enflasyona endekslenmesi enflasyonu kendi kendini besleyen bir sürece dönüştürür; bu atalet, dezenflasyonu zorlaştırır.'),
  ('Bankacılık sisteminde mevduatın büyük kısmının döviz cinsinden tutulduğu bir ekonomide para politikasının etkinliği için ne söylenebilir?', 'Faiz kararlarının kredi ve talep üzerindeki etkisi zayıflar', ['Faiz değişiklikleri çok daha güçlü ve hızlı etkiler, kur riski tamamen ortadan kalkar', 'Merkez bankası döviz basabildiği için etkinlik sınırsızdır', 'Para politikasının enflasyonla bağı tamamen kesilir ve fiyatlar sabitlenir'], 'Finansal dolarizasyon ulusal para cinsinden faiz kanalının kapsamını daraltır; ayrıca kur değişimleri bilançolar üzerinden güçlü etkiler yaratır.'),
  ('Yüksek enflasyonlu bir ülkede merkez bankası enflasyon yükselirken politika faizini indirirse kısa vadede kur ve enflasyon üzerinde hangi etki beklenir?', 'Ulusal para değer kaybeder ve enflasyon baskısı artar', ['Ulusal para değer kazanır ve enflasyon hemen düşerek hedefe iner', 'Kur ve enflasyon değişmez', 'Yalnızca işsizlik artar, fiyatlar etkilenmez'], 'Reel faizin daha da negatifleşmesi yerli paranın cazibesini azaltır; döviz talebi artar ve kurdan fiyatlara geçiş enflasyonu besler.'),
  ('Merkez bankası rezerv parasındaki artışın tamamen döviz alımlarından kaynaklandığı bir dönemde para politikası açısından hangi risk öne çıkar?', 'Sterilize edilmezse iç likidite ve enflasyon baskısı', ['Rezervlerin kendiliğinden ve kısa sürede tamamen erimesi', 'Ulusal paranın değerinin hızla düşmesi', 'Bankaların faiz gelirlerinin vergiden muaf tutulması'], 'Döviz alımı karşılığında piyasaya lira verilir; bu likidite çekilmezse kredi genişlemesi ve enflasyon baskısı doğabilir.'),
  ('1983\'ten beri ABD dolarına yaklaşık 7,8 kurla bağlı para kurulu benzeri bir düzen uygulayan ekonomi hangisidir?', 'Hong Kong', ['Singapur', 'Güney Kore', 'Tayvan'], 'Hong Kong 1983\'te bağlantılı kur sistemine geçti; Hong Kong doları dar bir bant içinde 7,8 civarında dolara bağlıdır.'),
  ('Bir ülkenin kendi parasını tamamen bırakıp ABD dolarını resmî para olarak kullanmasının para politikası açısından en temel sonucu hangisidir?', 'Bağımsız para politikası ve senyoraj gelirinin kaybedilmesi', ['Faizlerin ABD faizlerinden kalıcı olarak daha düşük olması', 'Ülkenin kendi merkez bankasının daha fazla para basabilmesi', 'Enflasyonun her durumda ABD\'den yüksek olması ve kurun dalgalanması'], 'Resmî dolarizasyonda faiz kararları fiilen ABD Merkez Bankasınca alınır; ülke kendi parasını basmadığı için senyoraj gelirini de yitirir.'),
  ('Para kurulu ile sıradan sabit kur sistemi arasındaki temel fark hangisidir?', 'Para kurulunda kur ve tam döviz karşılığı yasayla güvence altındadır', ['Sıradan sabit kurda hiç döviz rezervi tutulmaz ve kur her gün dalgalanır', 'Para kurulunda faiz merkez bankasınca serbestçe belirlenir', 'Sıradan sabit kur yalnızca altına bağlanabilir'], 'Para kurulunda bağlılık yasal düzenlemeyle güçlendirilir ve tabanın tamamı rezervle karşılanır; sıradan sabit kurda ise hükümet kuru daha kolay değiştirebilir.'),
  ('Derin bir durgunlukta kamu harcamalarının artmasının satışları canlandırıp firmaları yeni yatırıma yöneltmesiyle özel yatırımın artmasına ne ad verilir?', 'İçine çekme (crowding-in) etkisi', ['Dışlama etkisi ve faiz baskısıyla yatırım kaybı', 'Ricardocu denklik', 'Olivera-Tanzi etkisi'], 'Atıl kapasitenin bulunduğu dönemlerde talep artışı hızlandıran etkisiyle özel yatırımı uyarabilir; bu, dışlamanın tersi olan içine çekme etkisidir.'),
  ('Bir ülkede piyasa gelirlerine göre Gini katsayısı 0,50, vergi ve transferler sonrası harcanabilir gelire göre 0,30\'dur. Bu fark neyi gösterir?', 'Maliye politikasının gelir eşitsizliğini önemli ölçüde azalttığını', ['Maliye politikasının eşitsizliği artırdığını ve gelirleri üst gruplara aktardığını', 'Vergi sisteminin hiçbir bölüşüm etkisi olmadığını', 'Piyasa gelirlerinin tamamen eşit dağıldığını'], 'Gini\'nin 0,50\'den 0,30\'a düşmesi vergi ve transferlerin dağılımı belirgin biçimde düzelttiğini gösterir; Avrupa ülkelerinde bu tür farklar yaygındır.'),
  ('Yoksul hanelere yönelik nakit transferlerinin, aynı tutarda zengin hanelere yönelik vergi indirimine göre toplam talebi daha fazla artırması hangi kavramla açıklanır?', 'Düşük gelirlilerin marjinal tüketim eğiliminin daha yüksek olması', ['Zenginlerin marjinal tüketim eğiliminin 1\'den büyük olması ve gelirden fazla harcaması', 'Transferlerin vergiden muaf olması ve hiç harcanmaması', 'Vergi indirimlerinin ithalatı tamamen durdurması'], 'Düşük gelirli ve likidite kısıtlı haneler ek gelirin büyük kısmını harcar; yüksek gelirliler ise daha büyük bölümünü tasarruf eder.'),
  ('Hanehalklarına yapılan genel enerji sübvansiyonlarının bölüşüm açısından sıkça eleştirilmesinin nedeni hangisidir?', 'Daha çok enerji tüketen yüksek gelirlilerin sübvansiyondan daha büyük pay alması', ['Sübvansiyonların yalnızca en yoksul hanelere verildiği için enerji israfına ve aşırı tüketime yol açması', 'Enerji fiyatlarını yükseltmesi ve tüketimi azaltması', 'Bütçeye hiçbir maliyeti olmaması'], 'Fiyat sübvansiyonu tüketimle orantılı yarar sağlar; büyük ev ve çok araç sahibi haneler mutlak olarak daha fazla destek alır. Hedefli nakit desteği bu nedenle önerilir.'),
  ('ABD Merkez Bankasının Federal Açık Piyasa Komitesi olağan durumlarda yılda kaç kez planlı toplantı yapar?', '8', ['4', '12', '24'], 'FOMC yılda sekiz planlı toplantı yapar; gerektiğinde olağanüstü toplantılar da düzenlenebilir.'),
  ('Kriz dönemlerinde merkez bankalarının repo işlemlerinde kabul ettiği teminat listesini genişletmesinin amacı hangisidir?', 'Daha fazla bankanın elindeki varlıklarla likiditeye erişebilmesini sağlamak', ['Bankaların merkez bankasından borçlanmasını tamamen yasaklamak', 'Faiz koridorunu daraltarak politika faizini yükseltmek ve kredi büyümesini durdurmak', 'Devlet tahvillerinin satışını zorunlu kılmak'], 'Panik anında piyasada satılamayan varlıklar teminat olarak kabul edildiğinde bankalar likiditeye erişebilir ve zorunlu varlık satışlarının yarattığı fiyat çöküşü önlenir.'),
  ('Para arzı büyüme hızının kalıcı olarak artırılmasının uzun dönemde nominal faizleri, beklenen enflasyonu yükselterek artırmasına ne ad verilir?', 'Fisher etkisi', ['Likidite etkisi', 'Pigou etkisi', 'Gelir etkisi ve tüketim artışı'], 'Fisher etkisinde nominal faiz, beklenen enflasyondaki artış kadar yükselir; reel faiz uzun dönemde para büyümesinden bağımsızdır.'),
  ('Yüksek enflasyon beklentilerinin hâkim olduğu bir ekonomide merkez bankası para arzını hızla artırırsa uzun vadeli nominal faizler için en olası sonuç hangisidir?', 'Beklenen enflasyon arttığı için yükselir', ['Uzun vadeli faizler kesin olarak ve kalıcı biçimde sıfıra iner', 'Faizlerle enflasyon beklentisi arasındaki bağ kopar', 'Yalnızca kısa vadeli mevduat faizleri değişir'], 'Uzun vadeli faizler beklenen enflasyonu içerir; para büyümesi enflasyon beklentilerini yükseltirse likidite etkisi kısa sürede tersine döner.'),
  ('Hükümet büyük bir vergi indirimi yaparken merkez bankası aynı dönemde politika faizini sert biçimde yükseltiyor. Bu bileşimin faiz ve üretim üzerindeki etkisi için en doğru değerlendirme hangisidir?', 'Faizler belirgin biçimde yükselir; üretime net etki belirsizdir', ['Faizler kesin olarak düşer ve üretim her koşulda güçlü biçimde artar', 'Hem faizler hem üretim kesin olarak düşer', 'Faizler ve üretim hiç değişmez'], 'Genişletici maliye politikası ile daraltıcı para politikasının ikisi de faizi yükseltir; ancak biri talebi artırırken diğeri azalttığı için üretime net etki büyüklüklere bağlıdır.'),
  ('Tam istihdama yakın çalışan bir ekonomide \'bütçe açığı merkez bankasınca para basılarak kapatılsın, borçlanmaya gerek kalmasın\' önerisinin en olası sonucu hangisidir?', 'Toplam talep kapasiteyi aşar ve enflasyon yükselir', ['Enflasyon hiç değişmez, çünkü para basımının fiyatlarla hiçbir ilişkisi bulunmaz', 'Faizler kalıcı olarak yükselir ve para değer kazanır', 'Vergi gelirleri kendiliğinden artar ve açık kapanır'], 'Atıl kapasite yokken yeni para ile finanse edilen harcama reel üretimi artıramaz; fazla talep fiyatlara yansır.'),
  ('Bir ülkede hem yüksek enflasyon hem de yüksek işsizlik görülüyor ve bunun nedeni verimlilikteki düşüş gibi bir arz şokudur. Toplam talep politikalarının bu durumdaki sınırlılığı hangisidir?', 'Talebi artırmak enflasyonu, azaltmak işsizliği kötüleştirir', ['Talep politikaları her iki sorunu da aynı anda ve kalıcı olarak çözer', 'Talep politikalarının enflasyon ve işsizlik üzerinde hiçbir etkisi yoktur', 'Talep politikası yalnızca dış ticareti etkiler'], 'Arz kaynaklı sorunlarda talep yönlü politikalar ödünleşimle karşılaşır; kalıcı çözüm verimliliği artıran arz yönlü politikalardan beklenir.'),
  ('Merkez bankalarının elde ettiği kârın, gerekli yedekler ayrıldıktan sonra büyük ölçüde nereye aktarıldığı söylenebilir?', 'Hazine\'ye', ['Ticari bankaların hissedarlarına', 'Uluslararası Para Fonu\'na', 'Merkez bankası çalışanlarına ikramiye olarak dağıtılmak üzere personel fonuna'], 'Merkez bankası kârları, yasal yedeklerin ayrılmasının ardından büyük ölçüde Hazine\'ye aktarılır; bu nedenle senyoraj ve faiz gelirleri dolaylı olarak bütçeye katkı yapar.'),
  ('Merkez bankası bağımsızlığına yöneltilen \'demokratik meşruiyet\' eleştirisi neyi vurgular?', 'Seçilmemiş kişilerin toplumu derinden etkileyen kararlar alması', ['Merkez bankası yöneticilerinin her yıl halk oylamasıyla seçilmesi gerektiği', 'Merkez bankalarının vergi toplaması', 'Para politikasının hiçbir dağılım etkisinin olmaması'], 'Faiz kararları istihdamı ve servet dağılımını etkiler; eleştirmenler bu gücün hesap verebilirlikle dengelenmesi gerektiğini savunur.'),
  ('Durgunlukta faizler sıfıra yakınken hükümetin kamu yatırımını borçla finanse etmesinin, aynı yatırımı faizler yüksekken yapmasına göre avantajı hangisidir?', 'Borçlanma maliyetinin düşük olması ve dışlamanın zayıf kalması', ['Borcun hiçbir zaman geri ödenmemesinin yasal olarak güvenceye alınması', 'Vergi gelirlerinin kendiliğinden ve kalıcı olarak iki katına çıkması', 'Yatırımın ithalatı tamamen durdurması'], 'Düşük faizler projelerin finansman maliyetini azaltır; atıl kaynaklar nedeniyle özel yatırımın dışlanma riski de sınırlı kalır.'),
  ('Bir merkez bankası enflasyonla mücadele için faizi artırırken hükümet aynı dönemde kamu çalışanlarına enflasyonun çok üzerinde ücret artışı veriyor. Bu durumun dezenflasyona etkisi hangisidir?', 'Talep ve ücret baskısını artırarak dezenflasyonu zorlaştırır', ['Dezenflasyonu hızlandırır ve merkez bankasının faiz artırmasına gerek bırakmaz', 'Hiçbir etkisi olmaz çünkü ücretler fiyatları etkilemez', 'Yalnızca dış ticaret dengesini iyileştirir'], 'Para politikası talebi kısmaya çalışırken maliye politikası talebi genişletirse merkez bankası daha sert sıkılaşmak zorunda kalır; politika uyumsuzluğu maliyeti artırır.'),
  ('Bir merkez bankası yıl boyunca her toplantıda piyasa beklentisinden farklı bir karar alıyor. Bu durumun para politikasının etkinliğine olası zararı hangisidir?', 'Öngörülebilirlik azalır, risk primi ve oynaklık artar', ['Piyasalar politikayı daha iyi anlar ve beklentiler kalıcı olarak hedefe çapalanır', 'Faiz kararlarının hiçbir etkisi kalmaz ve enflasyon sıfırlanır', 'Bütçe açığı kendiliğinden kapanır'], 'Sürprizler zaman zaman gerekli olsa da sürekli öngörülemezlik beklentilerin yönetimini zorlaştırır; yatırımcılar belirsizlik için daha yüksek prim ister.'),
  ('Tüketim üzerinden alınan vergilerin gelir vergisine göre tasarruf açısından farkı nedir?', 'Tasarruf edilen kısmı vergilemediği için tasarrufu daha az caydırır', ['Tasarrufu gelir vergisinden daha ağır biçimde ve iki kez vergilendirir', 'Tasarruf ile tüketimi tamamen aynı oranda ve aynı anda vergilendirir', 'Yalnızca şirket kârlarını vergilendirir'], 'Gelir vergisi hem tasarruf edilen geliri hem de tasarrufun getirisini vergilerken tüketim vergisi yalnızca harcanan kısmı vergiler; bu nedenle tasarrufa daha nötrdür.'),
  ('Şirket kârının önce kurumlar vergisine, ardından dağıtılan kâr payı olarak ortakların gelir vergisine tabi tutulmasına yöneltilen temel eleştiri hangisidir?', 'Aynı gelirin iki kez vergilendirilmesi', ['Kârın hiçbir aşamada vergilendirilmemesi', 'Yalnızca işçi ücretlerinin vergilendirilmesi', 'Dolaylı vergilerin tamamen ortadan kalkması'], 'Ekonomik çifte vergilendirme, özsermaye finansmanını borç finansmanına göre pahalılaştırabilir; bu nedenle birçok ülke kâr payı istisnaları ya da kredileri uygular.'),
  ('Servet vergisine yöneltilen pratik eleştirilerden biri aşağıdakilerden hangisidir?', 'Varlıkların değerlemesinin zor olması ve sermaye kaçışına yol açabilmesi', ['Servet sahiplerinin hiç bulunmaması', 'Vergi gelirlerini her zaman sınırsız biçimde artırması ve bütçe fazlası yaratması', 'Yalnızca düşük gelirlileri etkilemesi'], 'Halka açık olmayan şirket payları, sanat eserleri gibi varlıklar kolay değerlenemez; hareketli sermaye düşük vergili ülkelere kayabilir.'),
  ('Bir hükümetin vergi tabanını genişletip oranları düşürmesi (geniş taban–düşük oran yaklaşımı) neden önerilir?', 'Aynı geliri daha az bozucu etkiyle toplamak için', ['Vergi gelirini kesinlikle azaltmak ve devleti küçültmek için', 'İstisnaları artırarak vergi sistemini karmaşıklaştırmak için', 'Yalnızca yabancı şirketleri vergilendirmek için'], 'İstisnaların azaltılması tabanı genişletir; böylece daha düşük oranlarla aynı gelir toplanır ve vergilerin ekonomik kararlar üzerindeki bozucu etkileri azalır.'),
  ('Bir ülkede vergi gelirlerinin büyük bölümünün dolaylı vergilerden oluşması maliye politikası açısından hangi sorunu doğurur?', 'Vergi yükünün ödeme gücüyle bağının zayıflaması', ['Vergi gelirlerinin enflasyondan hiç etkilenmemesi ve sabit kalması', 'Vergi toplama maliyetinin sınırsız biçimde artması', 'Gelir dağılımının kendiliğinden eşitlenmesi'], 'Dolaylı vergiler tüketime bağlıdır; düşük gelirliler gelirlerinin daha büyük kısmını tükettiği için bu vergiler ödeme gücü ilkesini zayıflatır.'),
  ('William Brainard\'ın 1967 tarihli çalışmasına göre, politika yapıcı para politikasının etkisinin büyüklüğü konusunda belirsizlik taşıyorsa en uygun tepki nedir?', 'Etkisi kesin bilinen duruma göre daha temkinli, daha küçük adımlarla hareket etmek', ['Etkisi kesin bilinen duruma göre daha sert ve daha büyük adımlarla hareket etmek', 'Politika aracını tümüyle devre dışı bırakıp piyasaya bırakmak', 'Her dönem aracı rastgele bir yönde değiştirmek'], 'Brainard ilkesine göre çarpan belirsizliği varken en iyi politika, belirsizliğin olmadığı duruma göre daha az agresiftir (zayıflatma ilkesi).'),
  ('Charles Goodhart\'ın adıyla anılan yasa, para politikası için neyi öne sürer?', 'Bir istatistiksel göstergenin politika hedefi yapıldığında, gösterge olarak güvenilirliğini yitirme eğiliminde olduğunu', ['Merkez bankası bilançosunun hiçbir zaman küçülemeyeceğini', 'Faiz oranlarının uzun vadede enflasyona eşit olacağını', 'Para arzı artışının reel gelirle birebir arttığını'], 'Goodhart yasası, düzenleyici baskı altına alınan bir parasal göstergenin ekonomik süreçlerle olan eski ilişkisini bozduğunu söyler; para hedeflemesinin terk edilmesinde etkili olmuştur.'),
  ('Trygve Haavelmo\'nun dengeli bütçe teoremine göre, hükümet harcamalarını vergilerle eşit miktarda artırırsa (yalnızca sabit vergili basit Keynesyen modelde) denge gelir nasıl değişir?', 'Gelir, harcama artışı kadar artar; çarpan 1\'dir', ['Gelir değişmez', 'Gelir, harcama artışının iki katı kadar artar', 'Gelir, harcama artışı kadar azalır'], 'Harcama çarpanı 1/(1-c), vergi çarpanı -c/(1-c) olduğundan toplamı (1-c)/(1-c)=1 eder. 100 birimlik dengeli artış geliri 100 birim artırır.'),
  ('Marjinal tüketim eğilimi 0,75 olan sabit vergili basit Keynesyen ekonomide hükümet harcamalarını ve vergileri 60 milyar TL artırıyor. Denge gelir ne kadar artar?', '60 milyar lira', ['240 milyar lira', '180 milyar lira', '15 milyar lira'], 'Harcama etkisi 60x4=240, vergi etkisi -60x3=-180 olur; net artış 60 milyar liradır. Dengeli bütçe çarpanı her zaman 1\'dir.'),
  ('Walter Bagehot\'un ünlü kuralına göre kriz anında son kredi mercii olarak merkez bankası nasıl davranmalıdır?', 'Sağlam teminat karşılığında, cezalandırıcı bir faizle, serbestçe ödünç vermelidir', ['Hiçbir kuruma ödünç vermemeli, bütün bankaların batmasına izin vermelidir', 'Teminatsız ve piyasa faizinin altında bir faizle yalnızca büyük bankalara ödünç vermelidir', 'Yalnızca Hazine\'ye kısa vadeli avans vermelidir'], 'Bagehot\'un 1873 tarihli Lombard Street kitabındaki kural, solvent ama likiditesi tükenen bankalara teminat karşılığı yüksek faizle sınırsız likidite sağlamaktır.'),
  ('Bir bankanın özkaynakları pozitif olduğu halde varlıklarını hızla nakde çevirememesi nedeniyle borçlarını ödeyememesi hangi risk türüne örnektir ve merkez bankasının son kredi mercii işlevini neden gündeme getirir?', 'Likidite krizi; merkez bankası geçici likidite sağlayarak solvent bankanın batmasını önleyebilir', ['Kur riski; merkez bankası bankanın yabancı para pozisyonunu kapatmakla yükümlüdür', 'Vergi riski; merkez bankası bankanın vergi borcunu silebilir', 'Enflasyon riski; merkez bankası varlık fiyatlarını sabitlemelidir'], 'Solvent ama illikit kurumlara sağlanan geçici destek, son kredi mercii işlevidir. Gerçekten batık bir kurumun kurtarılması ise mali otoriteyi ilgilendirir.'),
  ('Henry George\'un \'tek vergi\' önerisi hangi vergi tabanına dayanır?', 'Arazi değerine', ['Tüketim harcamalarına', 'Dış ticaret hacmine', 'Şirket kârlarına'], 'Henry George 1879 tarihli Progress and Poverty kitabında, arazi arzının sabit olması nedeniyle arazi rantının vergilendirilmesinin üretim kararlarını bozmayacağını savunmuştur.'),
  ('Arazi rantı üzerindeki vergiye ilişkin klasik görüşe göre bu verginin yansıtılamaması ve ölü ağırlık kaybı yaratmaması hangi varsayıma dayanır?', 'Arazi arzının fiyat esnekliğinin sıfır olması', ['Arazi talebinin sonsuz esnek olması', 'Arazi sahiplerinin vergiyi ödememesi', 'Arazi fiyatlarının devlet tarafından sabitlenmesi'], 'Arazi arzı sabitse vergi arzı değiştirmez; yük arazi sahibinde kalır ve kaynak dağılımı bozulmaz.'),
  ('Özel kesimin tasarruf-yatırım dengesi aynı kalmak üzere, bütçe açığı GSYH\'nin %3\'ü kadar artarsa ikiz açık özdeşliği uyarınca cari işlemler dengesi nasıl değişir?', 'Cari işlemler dengesi GSYH\'nin %3\'ü kadar bozulur', ['Cari işlemler dengesi GSYH\'nin %3\'ü kadar iyileşir', 'Cari işlemler dengesi değişmez', 'Cari açık GSYH\'nin %6\'sı kadar artar'], '(S-I)=(T-G)+(X-M) özdeşliğinde S-I sabitken T-G 3 puan azalırsa X-M de 3 puan azalmak zorundadır.'),
  ('Ricardocu denklik önermesinin geçerli olabilmesi için aşağıdaki koşullardan hangisi gerekir?', 'Hanehalklarının ileriyi gören, borç kısıtı olmayan ve gelecek kuşakları da kendi bütçesinde sayan davranışta bulunması', ['Merkez bankasının faizi sıfıra çekmesi', 'Vergilerin yalnızca dolaylı vergilerden oluşması', 'Kamu harcamalarının her yıl bütçe açığıyla artması'], 'Barro (1974) modeline göre hanehalkı bugünkü vergi indirimini gelecekteki vergi artışı beklentisiyle tasarrufa çevirir; likidite kısıtı ve kısa ufuk denkliği zayıflatır.'),
  ('Politika faizi sıfıra yakınken merkez bankası \'faizi uzun süre düşük tutacağını\' taahhüt ederse bu taahhüt hangi kanaldan ekonomiyi canlandırmayı hedefler?', 'Beklentiler kanalı: uzun vadeli faizlerin ve gelecekteki kısa vadeli faiz beklentilerinin düşmesi', ['Zorunlu karşılık kanalı: bankaların rezerv oranının sıfırlanması', 'Vergi kanalı: gelir vergisi oranlarının düşmesi', 'Dış borç kanalı: döviz borcunun silinmesi'], 'Uzun vadeli faiz, beklenen kısa vadeli faizlerin ortalamasına yakın olduğundan düşük faiz taahhüdü getiri eğrisini aşağı çeker.'),
  ('Faiz koridorunun üst sınırını oluşturan, bankaların merkez bankasından gecelik borç aldığı olanağa ne ad verilir?', 'Marjinal fonlama (borç verme) faizi', ['Rezerv opsiyonu katsayısı', 'Kısa vadeli reeskont oranı', 'Dolaylı kur payı'], 'Koridor sisteminde marjinal fonlama (lombard/borç verme) faizi tavanı, gecelik borçlanma (borç alma) faizi tabanı oluşturur; piyasa faizi bu aralıkta kalır.'),
  ('Yıllık geliri 100 bin TL\'ye kadar %10, bu tutarın üzerindeki kısım için %30 oranında vergilendiriliyor. 150 bin TL gelirli bir kişinin ortalama vergi oranı yaklaşık kaçtır?', '%16,7', ['%20,0', '%30,0', '%25,0'], 'Vergi = 10.000 + 0,30x50.000 = 25.000 TL; ortalama oran 25.000/150.000 ≈ %16,7\'dir. Marjinal oran %30 olduğundan ortalama orandan yüksektir.'),
  ('Enflasyon yüksekken gelir vergisi dilimleri her yıl güncellenmezse, nominal geliri artan ama reel geliri değişmeyen mükellefler ne yaşar?', 'Daha yüksek bir vergi dilimine geçerek reel vergi yükünün artması', ['Vergi yükünün otomatik olarak azalması', 'Vergi dilimlerinin kendiliğinden sıfırlanması', 'Hiçbir değişiklik olmaması'], 'Bu duruma dilim kayması (bracket creep) denir; enflasyon, artan oranlı vergi sisteminde yasa çıkarılmadan fiilî vergi artışı yaratır.'),
  ('Bir hükümet kişi başına eşit tutarda ve davranışlarından bağımsız bir götürü (kafa) vergisi koyarsa bu verginin ekonomik açıdan en önemli özelliği nedir?', 'Çalışma ve tüketim kararlarını bozmadığı için ölü ağırlık kaybı yaratmaması', ['Gelir adaletini mükemmel biçimde sağlaması', 'Kamu gelirlerini mutlaka azaltması', 'Enflasyonu sıfıra indirmesi'], 'Götürü vergi, marjinal kararları değiştirmediğinden verimlilik açısından idealdir; ancak ödeme gücüne bakmadığı için adalet bakımından eleştirilir.'),
  ('Borç/GSYH oranını %80\'de sabit tutmak isteyen ve nominal büyümenin %5 olduğu bir ülkede, uzun dönemde sürdürülebilecek bütçe açığı GSYH\'nin yüzde kaçıdır?', '%4', ['%5', '%16', '%1,6'], 'Durağan durumda borç oranı = açık oranı / nominal büyüme olduğundan açık = 0,80x0,05 = %4\'tür.'),
  ('Ödemesine 91 gün kalan, nominal değeri 100 TL olan iskontolu bir Hazine bonosu için piyasa basit yıllık faizi %40 ise, bonoun fiyatı yaklaşık kaç TL\'dir?', '90,93 TL', ['60,00 TL', '96,00 TL', '86,00 TL'], 'Fiyat = 100 / (1 + 0,40x91/365) ≈ 90,93 TL\'dir. Faiz yükseldikçe fiyat düşer.'),
  ('Bir devlet, dar bir mal grubundaki tüketimi azaltmak istiyor ve vergi geliri de beklentisindedir. Bu amaçla hangi vergi türü en uygun görünür?', 'Seçilmiş mallar üzerinde ÖTV benzeri bir tüketim vergisi', ['Götürü kafa vergisi', 'Miras vergisi', 'Kurumlar vergisi istisnası'], 'Seçili mallara getirilen tüketim vergisi hem tüketimi caydırır hem gelir sağlar; kafa vergisi veya kurumlar vergisi istisnası malın tüketimini etkilemez.'),
  ('Tam istihdam hasılasında ölçülen bütçe dengesine ne ad verilir?', 'Yapısal (konjonktürden arındırılmış) bütçe dengesi', ['Nominal ödemeler dengesi', 'Sermaye hesabı dengesi', 'Kasa esaslı denge'], 'Yapısal denge, konjonktürün etkilediği gelir ve harcama kalemlerini potansiyel çıktı düzeyine göre ayarlar ve bütçenin duruşunu daha doğru yansıtır.'),
  ('AMB\'nin üye ülke hükümetlerine doğrudan kredi vermesini veya borç senetlerini doğrudan ihraç piyasasından satın almasını yasaklayan düzenlemenin gerekçesi nedir?', 'Parasal finansmanın enflasyonist olması ve merkez bankası bağımsızlığını zedeleme riski', ['Euro\'nun altına endeksli olması', 'Üye ülkelerin hiç borçlanmaması gerektiği', 'Faiz oranlarının yasa gereği sabit tutulması'], 'Hükümetlerin merkez bankasından para basarak finansman sağlaması, mali disiplini bozar ve fiyat istikrarını tehdit eder; yasak mali baskınlığı sınırlamayı amaçlar.'),
  ('1979\'da Fed Başkanı Paul Volcker liderliğinde uygulanan yeni operasyon yöntemi, neye odaklanıyordu?', 'Faizi doğrudan hedeflemek yerine para arzı büyümesini kontrol etmek için rezervleri hedeflemeye', ['Altın standardına dönmeye', 'Vergi oranlarını artırmaya', 'Döviz kurunu sabitlemeye'], 'Ekim 1979\'da Fed, enflasyonu düşürmek için faiz hedeflemesinden borçlanılmamış rezerv hedeflemesine geçti; faizler sert yükseldi ve enflasyon geriledi.'),
  ('Almanya\'da 1923 hiperenflasyonunu sona erdirmek için ne yapılmıştır?', 'Yeni bir para birimi (Rentenmark) çıkarılmış ve parasal finansman sınırlandırılmıştır', ['Altın rezervleri tümüyle satılmıştır', 'Bütün vergiler kaldırılmıştır', 'Reichsmark kamuoyuna dağıtılmış ve basım artırılmıştır'], 'Kasım 1923\'te çıkarılan Rentenmark, sınırlı arzı ve bütçe disipliniyle güveni geri getirmiş; 1924\'te Reichsmark ile yer değiştirmiştir.'),
  ('Nordhaus\'un politik konjonktür modeline göre, seçmenler kısa görüşlüyse seçim öncesi dönemde yönetimin hangi eğilimi göstermesi beklenir?', 'Seçimden önce genişletici politikalarla işsizliği düşürmeye, seçimden sonra sıkılaştırmaya', ['Seçimden önce vergileri artırmaya', 'Seçimden önce hiçbir harcama yapmamaya', 'Seçim sonrası bütçe açığını artırmaya'], 'Nordhaus (1975), Phillips eğrisi ilişkisinden yararlanan iktidarların seçim öncesi işsizliği azaltmak için canlandırma, seçim sonrası enflasyonla mücadele için daralma yapacağını öne sürmüştür.'),
  ('Maliye politikasında \'sıfır tabanlı bütçe\' yaklaşımının ayırt edici özelliği nedir?', 'Her harcamanın her dönem sıfırdan gerekçelendirilmesi, geçmiş yıl harcamalarının otomatik olarak devam etmemesi', ['Hiçbir kamu harcaması yapılmaması', 'Bütçe gelirlerinin sıfır kabul edilmesi', 'Bütçenin yalnızca para tabanına bağlanması'], 'Sıfır tabanlı bütçelemede her harcama kalemi, önceki yılın tabanı dikkate alınmadan baştan savunulur ve öncelik sırasına konur.'),
  ('Ülkedeki bütün bankaların toplam mevduatı 1.000 birim, zorunlu karşılık oranı %10\'dur ve bankalar hiç aşırı rezerv tutmuyor. Merkez bankası zorunlu karşılık oranını %12,5\'e çıkarırsa, mevduatın aynı miktarda rezerv ile desteklenebilecek en yüksek düzeyi ne olur?', '800 birim', ['1.250 birim', '900 birim', '1.200 birim'], 'Mevcut rezerv 1.000x0,10=100\'dür. Yeni oranda en yüksek mevduat 100/0,125=800 birimdir; sistem mevduatı 200 birim küçültmek zorundadır.'),
  ('Richard Kahn\'ın 1931\'de ortaya koyduğu çarpan kavramı, kamu harcamalarının hangi sonucunu açıklar?', 'Başlangıç harcamasının, ardışık tüketim turlarıyla gelirde daha büyük bir artışa yol açmasını', ['Kamu harcamalarının her zaman özel yatırımı bire bir azaltmasını', 'Vergi gelirlerinin sürekli sabit kalmasını', 'Faiz oranlarının sıfıra inmesini'], 'Kamu harcaması bir kişinin geliri olur, bunun tüketilen kısmı bir başkasının geliri olur; seri 1/(1-c) kadar toplam gelir artışı yaratır.'),
  ('Alvin Hansen\'in 1938\'de öne sürdüğü \'seküler durgunluk\' hipotezi neyi savunur?', 'Yatırım fırsatlarının tükendiği bir olgun ekonomide yetersiz talebin uzun süre sürebileceğini', ['Enflasyonun her zaman talep fazlasından doğacağını', 'Kamu borcunun her zaman azaldığını', 'Para arzının ekonomiyi hiç etkilemediğini'], 'Hansen, nüfus artışının yavaşlaması ve yenilik fırsatlarının azalmasıyla tasarruf fazlasının kalıcı olabileceğini ve kamu harcamalarının gerekli olacağını savunmuştur.'),
  ('Klasik ekonomistlere atfedilen Say yasasını kabul eden bir görüşün para ve maliye politikasına bakışı nasıl olur?', 'Genel talep yetersizliği olmayacağından aktif talep yönetimine gerek görülmez', ['Her durgunlukta kamu harcamalarının artırılması şarttır', 'Merkez bankası faizi her zaman sıfıra çekmelidir', 'Vergi gelirleri tümüyle kaldırılmalıdır'], 'Say yasası \'arz kendi talebini yaratır\' der; bu görüşe göre kalıcı genel aşırı üretim yoktur, politika uygulamalarıyla talep yönetimi gereksizdir.'),
  ('Olivera-Tanzi etkisi yüksek enflasyonlu bir ekonomide bütçeyi nasıl etkiler?', 'Vergilerin tahakkuk ile tahsil arasında geçen sürede reel değerinin erimesiyle reel vergi gelirlerini azaltır', ['Kamu harcamalarının reel değerini artırır', 'Faiz ödemelerini sıfırlar', 'Para basımını yasaklar'], 'Vergi borcu gecikmeli ödendiğinde enflasyon nedeniyle reel değeri düşer; bu da bütçe açığını büyütür ve enflasyonu körükler.'),
  ('Merkez bankasının bankalara iskonto penceresinden (reeskont) verdiği kredinin faiz oranını yükseltmesi, bankaların davranışını nasıl etkiler?', 'Rezerv ihtiyaçlarını bu yolla karşılamanın maliyeti artar; bankalar kredi vermede daha temkinli olur', ['Bankaların daha fazla kredi vermesini sağlar', 'Para çarpanını sonsuza götürür', 'Devlet harcamalarını otomatik azaltır'], 'Reeskont/iskonto faizindeki artış borçlanmayı pahalılaştırır; bankalar likidite tamponu tutmaya ve kredi büyümesini sınırlamaya yönelir.'),
  ('Yıllık mali sürdürülebilirlik göstergesi olarak \'faiz giderleri/vergi gelirleri\' oranı yükseldiğinde bu durum neyi gösterir?', 'Kamu gelirlerinin daha büyük bir kısmının borç servisine ayrıldığını', ['Kamu borcunun azaldığını', 'Vergi tabanının genişlediğini', 'Bütçe harcamalarının eğitimde yoğunlaştığını'], 'Faiz/gelir oranı yükselirse bütçe esnekliği azalır; diğer kamu hizmetleri için kaynak daralır ve borç sürdürülebilirliği zayıflar.'),
  ('Merkez bankasının aşırı rezerv sahibi bankalara rezerv bakiyeleri üzerinden faiz ödemesi, para piyasası faizi üzerinde nasıl bir etki yaratır?', 'Piyasa faizinin ödenen rezerv faizinin altına inmesini engeller; bir taban oluşturur', ['Piyasa faizini sıfıra iter', 'Piyasa faizini politika faizinin üzerine çıkarır', 'Faizi tümüyle belirsiz hale getirir'], 'Bankalar merkez bankasında risksiz olarak rezerv faizi kazanabildiğinden daha düşük faizle ödünç vermez; bu, taban sisteminde faizin alt sınırıdır.'),
  ('Bir devletin sürekli yüksek bütçe açığı vermesi sonucu kamu borç stokunun artması, orta vadede faiz oranlarını nasıl etkileyebilir?', 'Borç talebinin ve risk priminin artmasıyla faizleri yukarı itebilir', ['Faizleri kesin olarak sıfıra çeker', 'Faizleri yasayla sabitler', 'Faizler üzerinde hiçbir etkisi olmaz'], 'Daha fazla devlet borçlanması fon talebini artırır; ayrıca borç sürdürülebilirliği endişesi risk primini yükseltir. Etkinin büyüklüğü ülkeden ülkeye değişir.'),
  ('Vergi mevzuatında bir malın \'vergi harcaması\' kapsamına girmesi ne anlama gelir?', 'Devletin belirli bir faaliyeti teşvik etmek için vergiden vazgeçerek gelirden feragat etmesi', ['Devletin o mal için doğrudan ödeme yapması', 'Malın ithalatının yasaklanması', 'Malın vergi dairesine devredilmesi'], 'İstisna, muafiyet ve indirim gibi vergi harcamaları doğrudan harcama yerine vergi sistemi aracılığıyla yapılan destektir ve bütçe gelirlerini azaltır.'),
  ('Marjinal tüketim eğilimi 0,6 olan sabit vergili bir ekonomide hükümet transferleri 100 milyar TL artarsa denge gelir kaç milyar TL artar?', '150', ['250', '60', '100'], 'Transfer çarpanı c/(1-c) = 0,6/0,4 = 1,5\'tir; 100x1,5 = 150 milyar TL.'),
  ('Kamu harcamaları yerine aynı tutarda vergi indirimi yapıldığında, basit Keynesyen modelde gelir artışı daha küçük çıkar. Bunun nedeni nedir?', 'Vergi indiriminin bir kısmının tasarrufa gitmesi', ['Vergi indiriminin enflasyonu düşürmesi', 'Vergi indiriminin kuru sabitlemesi', 'Vergi indiriminin kamu borcunu sıfırlaması'], 'Harcama doğrudan talebe eklenirken vergi indirimi önce hanehalkı gelirini artırır; bunun yalnız c oranı kadarı harcanır, dolayısıyla çarpan 1 birim daha küçüktür.'),
  ('Para politikasında \'güvenilirlik\' kavramı, hangi durumda dezenflasyon maliyetini azaltır?', 'Kamuoyunun hedefe inanması beklentileri ve ücret pazarlıklarını aşağı çekmesi', ['Hükümetin faizi hep aynı tutması', 'Bankaların kredi vermeyi bırakması', 'Vergi oranlarının sıfırlanması'], 'Güvenilir bir merkez bankasında beklenen enflasyon hedefe yaklaştığından ücret ve fiyat belirleme davranışı değişir; feda oranı düşer.'),
  ('Merkez bankası bono alımı yapıp bankalara rezerv sağladığında hangi bilanço kalemleri değişir?', 'Merkez bankasının varlığında menkul kıymetler, yükümlülüğünde bankaların rezervleri artar', ['Aktifinde altın azalır, pasifinde özkaynak artar', 'Pasifinde banknot azalır, aktifinde döviz düşer', 'Yalnızca Hazine hesabı artar'], 'Menkul kıymet alımı aktifi, ödeme olarak yaratılan rezerv ise pasifi aynı miktarda büyütür; para tabanı artar.'),
  ('Bir ülkede merkez bankası, enflasyon beklentilerinin hedefin üzerinde sabitlendiğini görüyor. Bu durumda en mantıklı politika adımı hangisidir?', 'Beklentileri çıpalamak için faiz artırımı ve açık iletişim', ['Faizi düşürüp serbest bırakmak', 'Zorunlu karşılığı sıfırlamak', 'Bütçe açığını büyütmek'], 'Beklentiler sabitlenince enflasyon yapışkan olur; güvenilir sıkılaştırma ve iletişim, ücret-fiyat davranışını hedefe yaklaştırır.'),
  ('Hazine\'nin döviz cinsi borçlarının yüksek olduğu bir ülkede ulusal para değer kaybederse kamu borç oranına etkisi ne olur?', 'Borç/GSYH oranı artar', ['Borç/GSYH oranı azalır', 'Değişmez', 'Borç otomatik silinir'], 'Döviz borcunun ulusal para karşılığı kurla orantılı büyür; GSYH ulusal parayla ölçüldüğünden oran yükselir.'),
  ('Politika faizi sıfırın altına inebilir mi sorusuna ilişkin hangi ifade doğrudur?', 'Bazı merkez bankaları mevduat faizini hafifçe negatif yapmıştır; ancak nakit tutma seçeneği alt sınırı belirler', ['Faiz yasa gereği asla sıfırın altına inemez', 'Negatif faiz her zaman altın standardı gerektirir', 'Negatif faiz yalnızca Hazine tarafından belirlenir'], 'İsviçre, Danimarka, Japonya ve AMB gibi merkez bankaları 2010\'larda negatif mevduat faizi uygulamıştır; banknot taşıma maliyeti etkin alt sınırı belirler.'),
  ('Parasalcı görüşün temsilcilerinden Milton Friedman\'a göre para politikasının uygulanmasında hangi kural tercih edilmelidir?', 'Para arzının sabit ve öngörülebilir bir oranda büyütülmesi', ['Her ay faizin rastgele ayarlanması', 'Konjonktüre göre sürekli ince ayar', 'Para arzının tamamen durdurulması'], 'Friedman, uzun ve değişken gecikmeler nedeniyle takdirî ince ayarın istikrarsızlık yaratacağını, k-yüzde kuralı gibi sabit bir büyüme kuralının yeğ olduğunu savunmuştur.'),
  ('Merkez bankasının politika faizini açıklayarak yalnızca gecelik faizi hedeflediği sistemde hangi değişken piyasaca belirlenir?', 'Para arzı miktarı', ['Politika faizi düzeyi', 'Reeskont kurulu üyeleri', 'Vergi oranı'], 'Faiz hedeflenince merkez bankası talebi karşılayacak kadar rezerv sağlar; para miktarı içsel olarak oluşur.'),
  ('IS eğrisi çok dik (yatırım faize duyarsız), LM eğrisi yatay (likidite tuzağı) iken hangi politika daha etkilidir?', 'Maliye politikası', ['Para politikası', 'İkisi de etkisiz', 'Yalnızca döviz müdahalesi'], 'Likidite tuzağında para arzı artışı faizi düşürmez; maliye genişlemesi faizi yükseltmeden geliri artırır, dışlama etkisi oluşmaz.'),
  ('Vergi tahsilatında etkinliği artırmak için dolaylı vergilerin ağırlığını artırmanın bir sakıncası nedir?', 'Düşük gelirlilerin gelirlerine oranla daha fazla yük taşıması', ['Verginin yalnız zenginlerden alınması', 'Enflasyonun düşmesi', 'Vergi toplamanın imkânsız hale gelmesi'], 'Dolaylı vergiler gelirden bağımsız ödendiği için düşük gelirli kesimlerde gelire oranla daha ağır yük doğurur (gerileyici etki).'),
];
